  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D4-EXEC-001-CONSTRUCT', 'construct'::public.t3a_content_family, 'D4 construct', 'D4', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"situation_classes": {"SC-D4-1": {"situation": "A question is put to the participant in front of others and an answer is expected before they can prepare one", "pattern_family": "IPF-D4-01"}, "SC-D4-2": {"situation": "Information must be given to a party the source establishes will be adversely affected by it", "pattern_family": "IPF-D4-02"}, "SC-D4-3": {"situation": "A statement attributed to the participant is contradicted or misrepresented by the record", "pattern_family": "IPF-D4-03"}, "SC-D4-4": {"situation": "Two sources of instruction the participant must answer to have given conflicting directions", "pattern_family": "IPF-D4-04"}, "SC-D4-5": {"situation": "A communication has escalated beyond the people who began it", "pattern_family": "IPF-D4-05"}, "SC-D4-6": {"situation": "A request is made which the source establishes cannot be granted as asked", "pattern_family": "IPF-D4-06"}, "SC-D4-7": {"situation": "The communication must reach a party for whom the standard channel, form or timing is unavailable", "pattern_family": "IPF-D4-07"}}, "conduct_elements": {"CE-D4-01": {"name": "Addressee", "supports": "Who was addressed is a fact of the record and needs no interpretation of manner", "does_not_support": "Does not support a claim about courage, avoidance or political skill in choosing an addressee"}, "CE-D4-02": {"name": "Material items contained", "supports": "The source designates the items before observation, so the selection is bounded and never judged by the mentor", "does_not_support": "Does not support a claim that the communication was complete, adequate or well judged, and never supports an inference from an omitted item about intent"}, "CE-D4-03": {"name": "Order of delivery", "supports": "Sequence is recoverable from the record and is the least interpretive fact available about a communication", "does_not_support": "Does not support any claim that a different order would have been better, or anything about structure as a skill"}, "CE-D4-04": {"name": "Responsiveness to what was asked", "supports": "Whether a question was answered is determinable from content alone, without reference to delivery", "does_not_support": "Does not support a claim of evasion, deflection or candour. An unanswered question is a recorded fact, not a motive"}, "CE-D4-05": {"name": "Separation of the known from the not known", "supports": "The source establishes what is and is not confirmed before observation, so the comparison is between two records", "does_not_support": "Does not support a claim about honesty, transparency or confidence"}, "CE-D4-06": {"name": "Correction of a contradicted statement", "supports": "The contradiction is authored into the source, so the opportunity is identical for every participant", "does_not_support": "Does not support a claim about assertiveness, self-advocacy or willingness to be corrected"}, "CE-D4-07": {"name": "Channel and timing", "supports": "Channels and points are pre-listed, so use is observable rather than judged", "does_not_support": "Does not support a claim that the channel chosen was the right one, or anything about judgment"}, "CE-D4-08": {"name": "Commitment to a further communication", "supports": "A stated follow-up is observable and is distinct from a delivery commitment, which is D2''s", "does_not_support": "Does not support a prediction that the follow-up would happen, or a judgment that it was sufficient"}, "CE-D4-09": {"name": "Conduct when the statement was put back", "supports": "The test point is authored into the source, so the opportunity is identical for every participant", "does_not_support": "Does not support a claim about consistency as a trait, composure or defensiveness"}}, "coverage": {"CE-D4-01": ["Carried", "Carried", "Carried", "Carried"], "CE-D4-02": ["Carried", "Carried", "Carried", "Carried"], "CE-D4-03": ["Carried", "Carried", "Carried", "Carried"], "CE-D4-04": ["Carried", "Carried", "Carried", "Carried"], "CE-D4-05": ["Carried", "Carried", "Carried", "Carried"], "CE-D4-06": ["Carried", "Carried", "NOT IN LAUNCH DESIGN", "NOT SERVED"], "CE-D4-07": ["NOT SERVED", "Carried", "Carried", "Carried"], "CE-D4-08": ["Carried", "Carried", "Carried", "Carried"], "CE-D4-09": ["Carried", "Carried", "NOT IN LAUNCH DESIGN", "Carried"]}, "source_fields": {"permitted_administration_variance": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The administration variance the source permits, recorded wherever it occurs"}, "unsupported_inferences": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The inferences the source must never support"}, "compatibility_class": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The delivery form class of the source, derived from its Stage"}, "recipient_roles": {"type": "list: RR", "stages": "1, 2, 3, 4", "holds": "The role labels the source establishes as addressable; consumed by Q-D4-01b"}, "intended_recipient": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The item of recipient_roles the source names as the intended recipient, by its identifier"}, "material_items": {"type": "list: MI, mapped", "stages": "1, 2, 3, 4", "holds": "The items the source designates as material to this communication, each quoted in the material map; consumed by Q-D4-02b and Q-D4-03b, each as its own determination"}, "designated_answer_contents": {"type": "list: AC", "stages": "1, 2, 3, 4", "holds": "The contents that answer the question the source puts; consumed by Q-D4-04b. A mentor never designates a content after observing"}, "unconfirmed_items": {"type": "list: UC, mapped", "stages": "1, 2, 3, 4", "holds": "The items the source records as unconfirmed at the moment of the communication, each quoted in the material map; consumed by Q-D4-05b"}, "available_channels": {"type": "list: CH", "stages": "1, 2, 3, 4", "holds": "The channels the source makes available whose use can complete and be evidenced at the Stage; consumed by Q-D4-07b"}, "designated_points": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The points at which the source establishes a communication may be made, or None"}, "question_put": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The exact text of the question the source puts to the participant, and where it is put, or None"}, "contradicted_attribution": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The statement attributed to the participant that the record contradicts, with both the attributed text and the record text, or None"}, "adverse_effect_party": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The role label of the party the source establishes will be adversely affected, or None"}, "escalation_state": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Whether the communication has already passed beyond its original participants, and to whom, or None"}, "conflicting_instructions": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The two or more directions the source establishes as conflicting, each with its source role, or None"}, "ungrantable_request": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The request the source establishes cannot be granted as asked, with the exact text that establishes it, or None"}, "statement_test_point": {"type": "point: Account test", "stages": "1, 2, 4", "holds": "The reveal or beat at which the participant''s own earlier statement is put back to them, or None"}, "list_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Why a list is empty, and any item withheld from a list as not selectable, or None"}, "source_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "A shared situation, a shared Stage 3 submission, a higher review standard or other situation context the source carries, or None"}, "situation_class_label": {"type": "text", "stages": "1, 2, 3, 4", "holds": "One approved generic phrase naming the kind of situation, its time sensitivity or consequence and the information available; never the source title or scenario detail"}, "observation_mode_label": {"type": "enum: written_response, structured_live_session, work_sample, group_session", "stages": "1, 2, 3, 4", "holds": "The observation mode of the Stage at which the source is served"}}, "source": "T3A-D4-EXEC-001 v2.2"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D4-EXEC-001-CONSTRUCT' and family = 'construct'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D4-EXEC-001-DETERMINATION', 'determination_question_set'::public.t3a_content_family, 'D4 determination set', 'D4', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"questions": {"Q-D4-01": {"element": "CE-D4-01", "capture_set": "C1", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D4-01b": {"element": "CE-D4-01", "capture_set": "C1b", "answer_type": "Bound selection, one or more", "source_bound_to": "recipient_roles", "served_when": "C1 records a party other than, or as well as, the intended recipient"}, "Q-D4-02": {"element": "CE-D4-02", "capture_set": "C2", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries material_items"}, "Q-D4-02b": {"element": "CE-D4-02", "capture_set": "C2b", "answer_type": "Bound selection, one or more", "source_bound_to": "material_items", "served_when": "C2 records designated items contained"}, "Q-D4-03": {"element": "CE-D4-03", "capture_set": "C3", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries two or more material_items"}, "Q-D4-03b": {"element": "CE-D4-03", "capture_set": "C3b", "answer_type": "Bound selection, one or more", "source_bound_to": "material_items", "served_when": "C3 records an order the record preserves"}, "Q-D4-04": {"element": "CE-D4-04", "capture_set": "C4", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries question_put"}, "Q-D4-04b": {"element": "CE-D4-04", "capture_set": "C4b", "answer_type": "Bound selection, one or more", "source_bound_to": "designated_answer_contents", "served_when": "C4 records designated contents used"}, "Q-D4-05": {"element": "CE-D4-05", "capture_set": "C5", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries unconfirmed_items"}, "Q-D4-05b": {"element": "CE-D4-05", "capture_set": "C5b", "answer_type": "Bound selection, one or more", "source_bound_to": "unconfirmed_items", "served_when": "C5 records items identified as unconfirmed"}, "Q-D4-06": {"element": "CE-D4-06", "capture_set": "C6", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries contradicted_attribution"}, "Q-D4-07": {"element": "CE-D4-07", "capture_set": "C7", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries available_channels, at Stages 2, 3 and 4"}, "Q-D4-07b": {"element": "CE-D4-07", "capture_set": "C7b", "answer_type": "Bound selection, one or more", "source_bound_to": "available_channels", "served_when": "C7 records a listed channel used"}, "Q-D4-08": {"element": "CE-D4-08", "capture_set": "C8", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D4-09": {"element": "CE-D4-09", "capture_set": "C9", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries statement_test_point"}}, "capture_sets": {"C1": {"title": "Who the communication was directed to", "lines": ["Addressed the party the source names as the intended recipient.", "Addressed a party from the source''s role list other than the intended recipient.", "Addressed the intended recipient and one or more other parties.", "Addressed no party during the observation."], "bound": null, "type": "content", "whole_session": "Addressed no party during the observation."}, "C1b": {"title": "Which of the listed roles were addressed", "lines": ["LISTED Selected each listed role the communication was addressed to.", "ADDRESSED_UNLISTED_ROLE Addressed a role outside the list and none of the listed roles.", "LISTED + ADDRESSED_UNLISTED_ROLE Selected the listed roles addressed and a role outside the list."], "bound": {"field": "recipient_roles", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C2": {"title": "Whether the communication contained the items the source designates as material", "lines": ["Contained one or more of the designated items.", "Made a communication containing none of the designated items.", "Made no communication during the observation."], "bound": null, "type": "content", "whole_session": "Made no communication during the observation."}, "C2b": {"title": "Which designated items the communication contained", "lines": ["LISTED Selected each designated item the communication contained.", "LISTED + CONTAINED_UNLISTED_ITEM Selected the designated items contained and an item outside the list."], "bound": {"field": "material_items", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C3": {"title": "The order in which the designated items were given", "lines": ["Gave two or more designated items in an order the record preserves.", "Gave two or more designated items with no order the record preserves.", "Gave at most one designated item during the observation."], "bound": null, "type": "content", "whole_session": "Gave at most one designated item during the observation."}, "C3b": {"title": "The sequence in which the designated items were given", "lines": ["LISTED Selected, in the order given, each designated item given.", "LISTED + ORDERED_UNLISTED_ITEM Selected, in the order given, the designated items given and an item outside the list in its place."], "bound": {"field": "material_items", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C4": {"title": "Whether the question the source puts was answered", "lines": ["Answered with one or more of the designated answer contents.", "Answered with content the source does not designate.", "Answered a question other than the one put.", "Did not answer the question put during the observation."], "bound": null, "type": "content", "whole_session": "Did not answer the question put during the observation."}, "C4b": {"title": "Which designated answer contents the answer used", "lines": ["LISTED Selected each designated content the answer used.", "LISTED + UNLISTED_ANSWER_CONTENT Selected the designated contents used and content outside the list."], "bound": {"field": "designated_answer_contents", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C5": {"title": "Whether items the source lists as unconfirmed were identified as unconfirmed", "lines": ["Stated listed unconfirmed items and identified each of them as unconfirmed.", "Stated listed unconfirmed items and identified some of them as unconfirmed and not others.", "Stated listed unconfirmed items and identified none of them as unconfirmed.", "Stated no listed unconfirmed item during the observation."], "bound": null, "type": "content", "whole_session": "Stated no listed unconfirmed item during the observation."}, "C5b": {"title": "Which listed unconfirmed items were identified as unconfirmed", "lines": ["LISTED Selected each listed item identified as unconfirmed.", "LISTED + IDENTIFIED_UNLISTED_ITEM Selected the listed items identified as unconfirmed and an item outside the list identified as unconfirmed."], "bound": {"field": "unconfirmed_items", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C6": {"title": "What was stated where the record contradicts an attributed statement", "lines": ["Stated what the record contains.", "Stated that the attributed statement was not accurate without stating what the record contains.", "Accepted the attributed statement as it was put.", "Stated nothing about the attributed statement during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about the attributed statement during the observation."}, "C7": {"title": "Which channel was used, and at which point", "lines": ["Used a listed channel at a point the source designates.", "Used a listed channel at a point the source does not designate.", "Used a channel the source does not list.", "Used no channel during the observation."], "bound": null, "type": "content", "whole_session": "Used no channel during the observation."}, "C7b": {"title": "Which listed channels were used", "lines": ["LISTED Selected each listed channel used.", "LISTED + USED_UNLISTED_CHANNEL Selected the listed channels used and a channel outside the list."], "bound": {"field": "available_channels", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C8": {"title": "Whether a further communication was stated", "lines": ["Stated a further communication naming its recipient and a time or condition.", "Stated a further communication naming its recipient and no time or condition.", "Stated a further communication without naming its recipient.", "Stated no further communication during the observation."], "bound": null, "type": "content", "whole_session": "Stated no further communication during the observation."}, "C9": {"title": "What was stated when the participant''s own earlier statement was put back", "lines": ["Stated the same content as the earlier statement.", "Stated content that differs from the earlier statement.", "Stated that the statement put back was not what had been said.", "Stated nothing about the earlier statement during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about the earlier statement during the observation."}}, "branch_rules": {"BR-D4-01": {"child": "Q-D4-01b", "parent": "Q-D4-01", "serving_answers": ["A2", "A3"], "note": "Which roles were addressed exists only once a party other than, or as well as, the intended recipient was addressed"}, "BR-D4-02": {"child": "Q-D4-02b", "parent": "Q-D4-02", "serving_answers": ["A1"], "note": "Which items were contained exists only once designated items were contained"}, "BR-D4-03": {"child": "Q-D4-03b", "parent": "Q-D4-03", "serving_answers": ["A1"], "note": "The sequence exists only once an order the record preserves was given"}, "BR-D4-04": {"child": "Q-D4-04b", "parent": "Q-D4-04", "serving_answers": ["A1"], "note": "Which contents were used exists only once the question was answered with designated content"}, "BR-D4-05": {"child": "Q-D4-05b", "parent": "Q-D4-05", "serving_answers": ["A1", "A2"], "note": "Which items were identified exists only once one or more were identified as unconfirmed"}, "BR-D4-06": {"child": "Q-D4-07b", "parent": "Q-D4-07", "serving_answers": ["A1", "A2"], "note": "Which channels exists only once a listed channel was used"}}, "source": "T3A-D4-EXEC-001 v2.2"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D4-EXEC-001-DETERMINATION' and family = 'determination_question_set'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D4-EXEC-001-STATEMENT-LIBRARY', 'statement_library'::public.t3a_content_family, 'D4 statement library', 'D4', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"comparison_operators": {}, "placeholder_grammar": {"addressed_role_count": {"kind": "count", "bound_to": "Q-D4-01b LISTED", "grammar": "whole number from 1 to the number of items in recipient_roles"}, "contained_item_count": {"kind": "count", "bound_to": "Q-D4-02b LISTED", "grammar": "whole number from 1 to the number of items in material_items"}, "ordered_item_count": {"kind": "count", "bound_to": "Q-D4-03b LISTED", "grammar": "whole number from 1 to the number of items in material_items"}, "answer_content_count": {"kind": "count", "bound_to": "Q-D4-04b LISTED", "grammar": "whole number from 1 to the number of items in designated_answer_contents"}, "unconfirmed_identified_count": {"kind": "count", "bound_to": "Q-D4-05b LISTED", "grammar": "whole number from 1 to the number of items in unconfirmed_items"}, "used_channel_count": {"kind": "count", "bound_to": "Q-D4-07b LISTED", "grammar": "whole number from 1 to the number of items in available_channels"}}, "recurrence_keys": {"REK-D4-001": {"element": "CE-D4-01", "proposition": "The intended recipient was or was not addressed", "material_variable": "Whether the identified party was addressed", "contextual_variable": "Which role; the setting"}, "REK-D4-002": {"element": "CE-D4-02", "proposition": "The communication did or did not contain the designated material items", "material_variable": "Whether designated items were contained", "contextual_variable": "Which items; the subject"}, "REK-D4-003": {"element": "CE-D4-03", "proposition": "The items were or were not given in a recoverable order", "material_variable": "Whether an order exists", "contextual_variable": "Which sequence"}, "REK-D4-004": {"element": "CE-D4-04", "proposition": "The question put was or was not answered", "material_variable": "Whether it was answered", "contextual_variable": "Which contents; the question"}, "REK-D4-005": {"element": "CE-D4-05", "proposition": "Unconfirmed items were or were not identified as unconfirmed", "material_variable": "Whether they were identified", "contextual_variable": "Which items"}, "REK-D4-006": {"element": "CE-D4-06", "proposition": "A contradicted attribution was or was not met with what the record contains", "material_variable": "Whether the record was stated", "contextual_variable": "Which attribution"}, "REK-D4-007": {"element": "CE-D4-07", "proposition": "A designated channel was or was not used at a designated point", "material_variable": "Whether both were designated", "contextual_variable": "Which channel; which point"}, "REK-D4-008": {"element": "CE-D4-08", "proposition": "A further communication was or was not stated with a recipient and a time", "material_variable": "Whether both were named", "contextual_variable": "To whom; by when"}, "REK-D4-009": {"element": "CE-D4-09", "proposition": "The restated content did or did not match the record of the earlier statement", "material_variable": "Whether it matched", "contextual_variable": "How far it differed"}}, "resolution_rules": {"RR-D4-01": {"pattern": "Q-D4-01=A2 + Q-D4-01b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent asserts a party other than the intended recipient was addressed and the child identifies none"}, "RR-D4-02": {"pattern": "Q-D4-01=A3 + Q-D4-01b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent asserts further parties were addressed and the child identifies none"}, "RR-D4-03": {"pattern": "Q-D4-02=A1 + Q-D4-02b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent asserts designated items were contained and the child identifies none"}, "RR-D4-04": {"pattern": "Q-D4-03=A1 + Q-D4-03b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent asserts an order and the child records no sequence"}, "RR-D4-05": {"pattern": "Q-D4-04=A1 + Q-D4-04b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent asserts designated content was used and the child identifies none"}, "RR-D4-06": {"pattern": "Q-D4-05=A1 + Q-D4-05b=UNANSWERED", "outcome": "REFUSE", "reason": "Unconfirmed items are recorded as identified and the child identifies none"}, "RR-D4-07": {"pattern": "Q-D4-05=A2 + Q-D4-05b=UNANSWERED", "outcome": "REFUSE", "reason": "Unconfirmed items are recorded as identified and the child identifies none"}, "RR-D4-08": {"pattern": "Q-D4-07=A1 + Q-D4-07b=UNANSWERED", "outcome": "REFUSE", "reason": "A listed channel is recorded as used and the child identifies none"}, "RR-D4-09": {"pattern": "Q-D4-07=A2 + Q-D4-07b=UNANSWERED", "outcome": "REFUSE", "reason": "A listed channel is recorded as used and the child identifies none"}, "RR-D4-10": {"pattern": "Q-D4-02=A2 + Q-D4-03=A1", "outcome": "REFUSE", "reason": "No designated item was contained, so no designated item can carry an order"}, "RR-D4-11": {"pattern": "Q-D4-02=A2 + Q-D4-03=A2", "outcome": "REFUSE", "reason": "No designated item was contained, so two or more cannot have been given"}, "RR-D4-12": {"pattern": "Q-D4-02=A3 + Q-D4-03=A1", "outcome": "REFUSE", "reason": "No communication was made, so no item can carry an order"}, "RR-D4-13": {"pattern": "Q-D4-02=A3 + Q-D4-03=A2", "outcome": "REFUSE", "reason": "No communication was made, so two or more items cannot have been given"}, "RR-D4-14": {"pattern": "Q-D4-01=A4 + Q-D4-02=A1", "outcome": "REFUSE", "reason": "No party was addressed, so nothing can have been contained in a communication"}, "RR-D4-15": {"pattern": "Q-D4-01=A4 + Q-D4-02=A2", "outcome": "REFUSE", "reason": "No party was addressed, so no communication was made"}, "RR-D4-16": {"pattern": "Q-D4-01=A1 + Q-D4-02=A3", "outcome": "REFUSE", "reason": "A party is recorded as addressed, so a communication was made"}, "RR-D4-17": {"pattern": "Q-D4-01=A2 + Q-D4-02=A3", "outcome": "REFUSE", "reason": "A party is recorded as addressed, so a communication was made"}, "RR-D4-18": {"pattern": "Q-D4-01