  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S1-001', 'source'::public.t3a_content_family, 'THE ROOM YOU WERE NOT EXPECTED IN', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE ROOM YOU WERE NOT EXPECTED IN", "source_digest": "1296e932383ab64e180413508c8226692721f02b3664590f36a0dd80d3389750", "situation": "It is your first day. You arrive at 8:45 AM for a 9:00 AM orientation and walk into what you believe is the orientation room on the third floor. Eight people are seated round a conference table with laptops open and documents spread out.\n\nAs you sit down and unpack your notebook, the person at the head of the table says: \"I''m sorry — who are you? This is a closed executive strategy meeting.\"\n\nYour orientation is on the second floor. Eight senior people are waiting for you to say something.", "reveals": [{"code": "R1", "text": "What do you say, word for word?", "role": "Opening"}, {"code": "R2", "text": "Who in the room are you saying it to?", "role": "Information"}, {"code": "R3", "text": "The person at the head of the table asks: \"And you are starting with which team?\" You do not yet know your team name; your offer letter names a department, not a team. What do you say?", "role": "Information"}, {"code": "R4", "text": "Is there anything you would send or say to anyone after you leave the room? To whom, and by when?", "role": "Information"}, {"code": "R5", "text": "Later that day the person from the head of the table passes you in the corridor and says: \"You said you were starting today — which department was it again?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles; R2 asks directly"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Three designated material items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R1 asks for the words, so an order is recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "question_put exists at R3"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The team name is recorded as unconfirmed"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "The source designates no available_channels item, so the bound question cannot be offered"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R4 asks about a further communication"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at R5"}], "material_map": [{"Item": "MI1", "Item text": "that the participant is in the wrong room", "Where the participant meets it": "The situation", "Quoted text": "Your orientation is on the second floor"}, {"Item": "MI2", "Item text": "that the participant is a new starter beginning today", "Where the participant meets it": "The situation", "Quoted text": "It is your first day"}, {"Item": "UC1", "Item text": "the team name", "Where the participant meets it": "Reveal R3", "Quoted text": "team name; your offer letter names a department, not a team"}], "source_sheet": {"d4_situation_class": "SC-D4-1", "workplace_demand": "Speaking to a room that did not expect you, with no time to prepare.", "relevant_conduct": "Who was addressed; which designated items the statement contained; the order; whether the question at R3 was answered; whether the unknown team name was identified as unknown; what further communication was stated; the answer at R5.", "irrelevant_conduct": "How the participant sounded, how quickly they responded, whether they seemed embarrassed. NONE OF THESE IS OBSERVED OR RECORDED.", "stated_standard": "\"This is a closed executive strategy meeting.\" Exact participant-facing text at the situation. Nothing in the source establishes what a new starter should say.", "stated_standard_source_quote_or_location": "\"This is a closed executive strategy meeting\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed. Screen-reader and extended-time accommodations permitted and recorded.", "unsupported_inferences": "That a short answer is better than a long one; that apologising was required; anything about presence or poise.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "recipient_roles": [{"id": "RR1", "text": "the person who asked, at the head of the table"}, {"id": "RR2", "text": "the room as a whole"}, {"id": "RR3", "text": "the person nearest the door"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the participant is in the wrong room"}, {"id": "MI2", "text": "that the participant is a new starter beginning today"}], "designated_answer_contents": [{"id": "AC1", "text": "the department named in the offer letter"}, {"id": "AC2", "text": "that the team within it is not yet known to the participant"}], "unconfirmed_items": [{"id": "UC1", "text": "the team name"}], "available_channels": [], "designated_points": "R1 and R3, both inside the room.", "question_put": "\"And you are starting with which team?\" Exact text at R3.", "contradicted_attribution": null, "adverse_effect_party": null, "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "R5", "list_note": "Not selectable in material_items: that the participant is leaving now, which the situation text does not establish.", "source_note": null, "situation_class_label": "A question put in front of others before an answer can be prepared", "observation_mode_label": "written_response", "min_seconds": 300, "max_seconds": 1200}, "source_identifier": "SRC-D4-S1-001", "stage_code": "S1", "source_version_hash": "1296e932383ab64e180413508c8226692721f02b3664590f36a0dd80d3389750", "serving_eligible": false, "verbatim": "It is your first day. You arrive at 8:45 AM for a 9:00 AM orientation and walk into what you believe is the orientation room on the third floor. Eight people are seated round a conference table with laptops open and documents spread out.\n\nAs you sit down and unpack your notebook, the person at the head of the table says: \"I''m sorry — who are you? This is a closed executive strategy meeting.\"\n\nYour orientation is on the second floor. Eight senior people are waiting for you to say something."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S1-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S1-002', 'source'::public.t3a_content_family, 'THE REQUEST OUTSIDE THE PROCESS', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE REQUEST OUTSIDE THE PROCESS", "source_digest": "057d109cdabd0f4e45729c1b50614c1e6049cd45a88a3cbe4521b58aeb2f3b3c", "situation": "You are a client services coordinator. Company policy states that all project scope changes require written approval from both the client''s project sponsor and your internal project manager before any work begins.\n\nA senior client contact calls you directly: \"I need your team to add three new data integrations to the dashboard by Friday. I know this isn''t in the original scope, but our chief executive is presenting to investors on Monday and he needs this data. I don''t have time for the formal change process. Can you just get it started and we''ll handle the paperwork later?\"\n\nYou know: the integrations would take about two weeks, an estimate not yet confirmed with your delivery team; the formal change process takes two to three days; your project manager is on leave until Wednesday; and the client contact is not the project sponsor named in the contract.", "reveals": [{"code": "R1", "text": "What do you say on the call, word for word?", "role": "Opening"}, {"code": "R2", "text": "Who else, if anyone, are you saying anything to, and what?", "role": "Information"}, {"code": "R3", "text": "The client contact asks: \"So can you start Monday or not?\" What do you say?", "role": "Information"}, {"code": "R4", "text": "What do you send after the call, to whom, and by when?", "role": "Information"}, {"code": "R5", "text": "On Wednesday your project manager says: \"I gather you told the client we could look at it. What exactly did you tell them?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles, including one the participant may choose to bring in"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "FOUR designated material items — the richest CE-D4-02 source in this bank"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R1 asks for the words"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A closed question is put at R3"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The estimate is recorded as unconfirmed"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "The source designates no available_channels item, so the bound question cannot be offered"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R4 asks what is sent, to whom and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at R5"}], "material_map": [{"Item": "MI1", "Item text": "that the request is outside the agreed scope", "Where the participant meets it": "The situation", "Quoted text": "I know this isn''t in the original scope"}, {"Item": "MI2", "Item text": "that written approval is required from two named parties before work begins", "Where the participant meets it": "The situation", "Quoted text": "written approval from both the client''s project sponsor and your internal project manager before any work begins"}, {"Item": "MI3", "Item text": "that the integrations would take about two weeks", "Where the participant meets it": "The situation", "Quoted text": "integrations would take about two weeks"}, {"Item": "MI4", "Item text": "that the change process itself takes two to three days", "Where the participant meets it": "The situation", "Quoted text": "change process takes two to three days"}, {"Item": "UC1", "Item text": "the two-week estimate, which has not been confirmed with the delivery team", "Where the participant meets it": "The situation", "Quoted text": "an estimate not yet confirmed with your delivery team"}], "source_sheet": {"d4_situation_class": "SC-D4-6", "workplace_demand": "Communicating a boundary to someone with standing to press against it.", "relevant_conduct": "Who was addressed; which designated items the statement contained; the order; whether the question at R3 was answered; whether the two-week estimate was identified as unconfirmed; what further communication was stated; the answer at R5.", "irrelevant_conduct": "Whether the participant was firm or accommodating; the commercial merits; the client''s urgency.", "stated_standard": "\"all project scope changes require written approval from both the client''s project sponsor and your internal project manager before any work begins.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"all project scope changes require written approval from both the client''s project sponsor and your internal project manager before any work begins\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That refusing was required; that a softer answer would have been better; anything about assertiveness.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "recipient_roles": [{"id": "RR1", "text": "the client contact on the call"}, {"id": "RR2", "text": "the project manager, on leave until Wednesday"}, {"id": "RR3", "text": "the client''s contracted project sponsor"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the request is outside the agreed scope"}, {"id": "MI2", "text": "that written approval is required from two named parties before work begins"}, {"id": "MI3", "text": "that the integrations would take about two weeks"}, {"id": "MI4", "text": "that the change process itself takes two to three days"}], "designated_answer_contents": [{"id": "AC1", "text": "that work cannot start Monday without the two approvals"}, {"id": "AC2", "text": "what would have to happen for work to start, and when"}], "unconfirmed_items": [{"id": "UC1", "text": "the two-week estimate, which has not been confirmed with the delivery team"}], "available_channels": [], "designated_points": "R1 and R3 on the call; R4 after it.", "question_put": "\"So can you start Monday or not?\" Exact text at R3.", "contradicted_attribution": null, "adverse_effect_party": "The client contact, who will not get what was asked.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": "\"Can you just get it started and we''ll handle the paperwork later?\" Exact text at the situation.", "statement_test_point": "R5", "list_note": null, "source_note": null, "situation_class_label": "A request that cannot be granted as asked", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D4-S1-002", "stage_code": "S1", "source_version_hash": "057d109cdabd0f4e45729c1b50614c1e6049cd45a88a3cbe4521b58aeb2f3b3c", "serving_eligible": false, "verbatim": "You are a client services coordinator. Company policy states that all project scope changes require written approval from both the client''s project sponsor and your internal project manager before any work begins.\n\nA senior client contact calls you directly: \"I need your team to add three new data integrations to the dashboard by Friday. I know this isn''t in the original scope, but our chief executive is presenting to investors on Monday and he needs this data. I don''t have time for the formal change process. Can you just get it started and we''ll handle the paperwork later?\"\n\nYou know: the integrations would take about two weeks, an estimate not yet confirmed with your delivery team; the formal change process takes two to three days; your project manager is on leave until Wednesday; and the client contact is not the project sponsor named in the contract."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S1-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S1-003', 'source'::public.t3a_content_family, 'THE UPDATE TAKEN APART IN THE ROOM', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE UPDATE TAKEN APART IN THE ROOM", "source_digest": "6476247f63143aa5216fbebd8fab5d16f15a81b5414070aec32353212aa031fd", "situation": "You are a junior analyst. You have just presented a project update to twelve people including your manager, two directors and your team.\n\nAs you finish, one of the directors says: \"I''m going to be blunt. This presentation was disorganised, the data was poorly sourced, and the recommendations are superficial at best. I expected more from this team.\"\n\nThe room is quiet. What the record shows: two of your four data sources are the client''s own figures, supplied last week; the third is an internal report from this quarter; the fourth is an estimate you built yourself and labeled as an estimate on slide six.", "reveals": [{"code": "R1", "text": "What do you say next, word for word?", "role": "Opening"}, {"code": "R2", "text": "Who are you saying it to?", "role": "Information"}, {"code": "R3", "text": "The director asks: \"Where did the numbers on slide four come from?\" What do you say?", "role": "Information"}, {"code": "R4", "text": "What, if anything, do you send after the meeting, to whom, and by when?", "role": "Information"}, {"code": "R5", "text": "The next morning your manager says: \"You told the room the figures were the client''s. Which ones were?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Three designated items, all about sourcing"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R1 asks for the words"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A specific question is put at R3"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The self-built estimate is the unconfirmed item, and identifying it is the element this source exercises best"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "The source designates no available_channels item, so the bound question cannot be offered"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R4 asks about a further communication"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at R5"}], "material_map": [{"Item": "MI1", "Item text": "that two of the four sources are the client''s own figures", "Where the participant meets it": "The situation", "Quoted text": "four data sources are the client''s own figures"}, {"Item": "MI2", "Item text": "that the third is an internal report from this quarter", "Where the participant meets it": "The situation", "Quoted text": "third is an internal report from this quarter"}, {"Item": "MI3", "Item text": "that the fourth is the participant''s own estimate and is labeled as one", "Where the participant meets it": "The situation", "Quoted text": "the third is an internal report from this quarter; the fourth is an estimate you built yourself and labeled as an estimate"}, {"Item": "UC1", "Item text": "the participant''s own estimate on slide six", "Where the participant meets it": "The situation", "Quoted text": "an internal report from this quarter; the fourth is an estimate you built yourself and labeled as an estimate on slide six"}], "source_sheet": {"d4_situation_class": "SC-D4-1", "workplace_demand": "Communicating about one''s own work immediately after it has been described as poor in front of others.", "relevant_conduct": "Who was addressed; which designated items the statement contained; the order; whether the question at R3 was answered with designated contents; whether the self-built estimate was identified as an estimate; the further communication stated; the answer at R5.", "irrelevant_conduct": "Composure, recovery, tone, whether the participant defended or conceded. NONE OF THESE IS OBSERVED OR RECORDED, AND NO CAPTURE LINE MAY REFER TO THEM.", "stated_standard": "\"the fourth is an estimate you built yourself and labeled as an estimate on slide six.\" Exact text at the situation. This is the record against which the account of sourcing is compared.", "stated_standard_source_quote_or_location": "\"the fourth is an estimate you built yourself and labeled as an estimate on slide six\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": "SENSITIVE_CONTENT", "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That the criticism was fair or unfair; that pushing back was required; anything about resilience, which is another dimension''s.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "recipient_roles": [{"id": "RR1", "text": "the director who spoke"}, {"id": "RR2", "text": "the room as a whole"}, {"id": "RR3", "text": "the participant''s manager"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that two of the four sources are the client''s own figures"}, {"id": "MI2", "text": "that the third is an internal report from this quarter"}, {"id": "MI3", "text": "that the fourth is the participant''s own estimate and is labeled as one"}], "designated_answer_contents": [{"id": "AC1", "text": "the client''s supplied figures, for the two lines that use them"}, {"id": "AC2", "text": "the internal report, for the line that uses it"}], "unconfirmed_items": [{"id": "UC1", "text": "the participant''s own estimate on slide six"}], "available_channels": [], "designated_points": "R1 and R3 in the room; R4 after it.", "question_put": "\"Where did the numbers on slide four come from?\" Exact text at R3.", "contradicted_attribution": null, "adverse_effect_party": null, "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "R5", "list_note": null, "source_note": "Higher review standard: The source places the participant in front of a room immediately after their work has been described as poor. Section 3.2 permits this as CONTEXT and permits D4 to observe only what was communicated in response — never how the participant absorbed it. No question here observes composure, recovery or manner, and the fairness drafting test must be discharged by someone who has read this note. contradicted_attribution: The director characterises the work; that is a statement by a character, NOT an attribution of words to the participant.", "situation_class_label": "A question put in front of others before an answer can be prepared", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D4-S1-003", "stage_code": "S1", "source_version_hash": "6476247f63143aa5216fbebd8fab5d16f15a81b5414070aec32353212aa031fd", "serving_eligible": false, "verbatim": "You are a junior analyst. You have just presented a project update to twelve people including your manager, two directors and your team.\n\nAs you finish, one of the directors says: \"I''m going to be blunt. This presentation was disorganised, the data was poorly sourced, and the recommendations are superficial at best. I expected more from this team.\"\n\nThe room is quiet. What the record shows: two of your four data sources are the client''s own figures, supplied last week; the third is an internal report from this quarter; the fourth is an estimate you built yourself and labeled as an estimate on slide six."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S1-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S1-004', 'source'::public.t3a_content_family, 'TWO MANAGERS, TWO INSTRUCTIONS', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "TWO MANAGERS, TWO INSTRUCTIONS", "source_digest": "b8e8da42df6b1cac66a8e083d16005d14921edd86261da086bce3121caaf2e5b", "situation": "You are a project coordinator reporting to two managers on a matrix project.\n\nYour direct manager emailed this morning: \"For the client proposal, use the standard pricing template. Keep it simple — they value straightforward pricing. No custom packages.\"\n\nTwenty minutes later the project lead said: \"For the client proposal, build three custom pricing tiers. They are a strategic account and we need to show flexibility. Don''t use the standard template.\"\n\nThe proposal is due tomorrow at noon. You cannot produce both. Neither manager knows the other has given you an instruction.", "reveals": [{"code": "R1", "text": "Who do you communicate with first, and what do you say, word for word?", "role": "Opening"}, {"code": "R2", "text": "Is anyone else told, and what are they told?", "role": "Information"}, {"code": "R3", "text": "Your direct manager replies: \"Which is it going to be?\" What do you say?", "role": "Information"}, {"code": "R4", "text": "What do you send before noon tomorrow, to whom, and containing what?", "role": "Information"}, {"code": "R5", "text": "After the proposal goes out the project lead says: \"You told me you''d go with the tiers. What did you tell the other side?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "THE PRIMARY ELEMENT OF THIS SOURCE. Which party was addressed first is the situation"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R1 asks for the words"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A closed question is put at R3"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The governing instruction is unresolved and recorded as such"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "The source designates no available_channels item, so the bound question cannot be offered"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R4 asks what is sent, to whom and containing what"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at R5, and it puts the participant''s own words back to them"}], "material_map": [{"Item": "MI1", "Item text": "that two conflicting instructions have been given", "Where the participant meets it": "The situation", "Quoted text": "given you an instruction"}, {"Item": "MI2", "Item text": "what each instruction was", "Where the participant meets it": "The situation", "Quoted text": "use the standard pricing template"}, {"Item": "MI3", "Item text": "that both cannot be produced by noon tomorrow", "Where the participant meets it": "The situation", "Quoted text": "due tomorrow at noon"}, {"Item": "MI4", "Item text": "that a decision is needed and by when", "Where the participant meets it": "The situation", "Quoted text": "The proposal is due tomorrow at noon"}, {"Item": "UC1", "Item text": "which instruction governs, which no one has yet decided", "Where the participant meets it": "The situation", "Quoted text": "Neither manager knows the other has given you an instruction"}], "source_sheet": {"d4_situation_class": "SC-D4-4", "workplace_demand": "Communicating about two instructions that cannot both be followed.", "relevant_conduct": "Who was addressed and in what order; which designated items each statement contained; whether the question at R3 was answered; whether the unresolved choice was identified as unresolved; the further communication stated; the answer at R5.", "irrelevant_conduct": "Which instruction is better; the managers'' relative seniority; whether the participant seemed decisive.", "stated_standard": "\"The proposal is due tomorrow at noon.\" Exact text at the situation. Nothing in the source ranks the two instructions.", "stated_standard_source_quote_or_location": "\"The proposal is due tomorrow at noon\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That either manager should have been told first; that going to both together is better than going to each; anything about diplomacy.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "recipient_roles": [{"id": "RR1", "text": "the direct manager"}, {"id": "RR2", "text": "the project lead"}, {"id": "RR3", "text": "both together"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that two conflicting instructions have been given"}, {"id": "MI2", "text": "what each instruction was"}, {"id": "MI3", "text": "that both cannot be produced by noon tomorrow"}, {"id": "MI4", "text": "that a decision is needed and by when"}], "designated_answer_contents": [{"id": "AC1", "text": "which of the two the participant will produce"}, {"id": "AC2", "text": "that the choice has not been made and who must make it"}], "unconfirmed_items": [{"id": "UC1", "text": "which instruction governs, which no one has yet decided"}], "available_channels": [], "designated_points": "R1, R3 and R4.", "question_put": "\"Which is it going to be?\" Exact text at R3.", "contradicted_attribution": null, "adverse_effect_party": null, "escalation_state": null, "conflicting_instructions": "The standard template from the direct manager; three custom tiers from the project lead. Both quoted at the situation.", "ungrantable_request": null, "statement_test_point": "R5", "list_note": null, "source_note": null, "situation_class_label": "Conflicting directions from two or more sources of instruction", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D4-S1-004", "stage_code": "S1", "source_version_hash": "b8e8da42df6b1cac66a8e083d16005d14921edd86261da086bce3121caaf2e5b", "serving_eligible": false, "verbatim": "You are a project coordinator reporting to two managers on a matrix project.\n\nYour direct manager emailed this morning: \"For the client proposal, use the standard pricing template. Keep it simple — they value straightforward pricing. No custom packages.\"\n\nTwenty minutes later the project lead said: \"For the client proposal, build three custom pricing tiers. They are a strategic account and we need to show flexibility. Don''t use the standard template.\"\n\nThe proposal is due tomorrow at noon. You cannot produce both. Neither manager knows the other has given you an instruction."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S1-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S1-005', 'source'::public.t3a_content_family, 'THE MESSAGE LEFT AT 7:15', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE MESSAGE LEFT AT 7:15", "source_digest": "d2ad4863eb8b09be483b45a410465bfb58058cd734df8738f16f077f47962281", "situation": "You are an account coordinator. You arrive Monday morning to a voicemail left at 7:15 AM by the client''s operations director:\n\n\"I am extremely disappointed. I was told by someone on your team that our implementation would be completed last week. I rearranged my department''s schedule around that date. Now I find out it has been pushed back two more weeks and no one told me — I had to find out from my own team. I expect a call back by 10:00 AM.\"\n\nWhat the record shows: the implementation was rescheduled eleven days ago; the revised date is in the project plan; the plan was sent to the client''s project inbox, not to the operations director; nobody on your team has a record of telling the operations director the original date would hold; and the revised completion date is two weeks from Friday, not two weeks from now.", "reveals": [{"code": "R1", "text": "Who do you contact, and what do you say, word for word?", "role": "Opening"}, {"code": "R2", "text": "Is anyone else contacted, and what are they told?", "role": "Information"}, {"code": "R3", "text": "The operations director asks: \"So when is it actually finished?\" What do you say?", "role": "Information"}, {"code": "R4", "text": "What do you send after the call, to whom, and by when?", "role": "Information"}, {"code": "R5", "text": "Your supervisor asks: \"They say we told them last week would hold. Did we?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles, one with a stated deadline"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R1 asks for the words"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A closed question with one designated content"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "Who told the client what is recorded as unconfirmed"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "DIRECT", "basis": "ONE OF ONLY TWO SOURCES IN THE ESTATE WHERE CE-D4-06 IS FULLY EXERCISED"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "The source designates no available_channels item, so the bound question cannot be offered"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R4 asks about a further communication"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at R5"}], "material_map": [{"Item": "MI1", "Item text": "the revised completion date, two weeks from Friday", "Where the participant meets it": "The situation", "Quoted text": "telling the operations director the original date would hold; and the revised completion date is two weeks from Friday, not two weeks"}, {"Item": "MI2", "Item text": "that the schedule changed eleven days ago", "Where the participant meets it": "The situation", "Quoted text": "eleven days ago; the"}, {"Item": "MI3", "Item text": "that the revised plan went to the project inbox", "Where the participant meets it": "The situation", "Quoted text": "revised date is in the project plan; the plan was sent to the client''s project inbox, not to the operations director; nobody"}, {"Item": "MI4", "Item text": "that no record exists of anyone stating the original date would hold", "Where the participant meets it": "The situation", "Quoted text": "nobody on your team has a record of telling the operations director the original date would hold; and the revised completion date"}, {"Item": "UC1", "Item text": "who, if anyone, told the operations director the original date would hold", "Where the participant meets it": "The situation", "Quoted text": "not to the operations director; nobody on your team has a record of telling the operations director the original date would hold"}], "source_sheet": {"d4_situation_class": "SC-D4-2", "workplace_demand": "Communicating with a party who has been adversely affected and is working from a different record.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order; whether the question at R3 was answered with the designated date; whether the unverified claim was identified as unverified; the further communication stated; the answer at R5.", "irrelevant_conduct": "Whether the client is justified; who failed to tell them, WHICH IS A D2 MATTER AND NOT OBSERVED HERE; whether the participant sounded apologetic.", "stated_standard": "\"the revised completion date is two weeks from Friday.\" Exact text at the situation. This is the record against which any date stated is compared.", "stated_standard_source_quote_or_location": "\"the revised completion date is two weeks from Friday\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That an apology was required; that the participant should defend the team; anything about empathy.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "recipient_roles": [{"id": "RR1", "text": "the client''s operations director"}, {"id": "RR2", "text": "the client''s project inbox"}, {"id": "RR3", "text": "the participant''s supervisor"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the revised completion date, two weeks from Friday"}, {"id": "MI2", "text": "that the schedule changed eleven days ago"}, {"id": "MI3", "text": "that the revised plan went to the project inbox"}, {"id": "MI4", "text": "that no record exists of anyone stating the original date would hold"}], "designated_answer_contents": [{"id": "AC1", "text": "the revised completion date, two weeks from Friday"}], "unconfirmed_items": [{"id": "UC1", "text": "who, if anyone, told the operations director the original date would hold"}], "available_channels": [], "designated_points": "Before 10:00 AM, at R1 and R3.", "question_put": "\"So when is it actually finished?\" Exact text at R3.", "contradicted_attribution": "The operations director attributes to the team a statement that the original date would hold, and the record holds no such statement. Both texts are at the situation.", "adverse_effect_party": "The client''s operations director.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "R5", "list_note": null, "source_note": null, "situation_class_label": "Information that will adversely affect the party who receives it", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D4-S1-005", "stage_code": "S1", "source_version_hash": "d2ad4863eb8b09be483b45a410465bfb58058cd734df8738f16f077f47962281", "serving_eligible": false, "verbatim": "You are an account coordinator. You arrive Monday morning to a voicemail left at 7:15 AM by the client''s operations director:\n\n\"I am extremely disappointed. I was told by someone on your team that our implementation would be completed last week. I rearranged my department''s schedule around that date. Now I find out it has been pushed back two more weeks and no one told me — I had to find out from my own team. I expect a call back by 10:00 AM.\"\n\nWhat the record shows: the implementation was rescheduled eleven days ago; the revised date is in the project plan; the plan was sent to the client''s project inbox, not to the operations director; nobody on your team has a record of telling the operations director the original date would hold; and the revised completion date is two weeks from Friday, not two weeks from now."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S1-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S1-006', 'source'::public.t3a_content_family, 'THE AWARD THAT THE RECORD ACCOUNTS FOR', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE AWARD THAT THE RECORD ACCOUNTS FOR", "source_digest": "999f00187ac7a3e96c6246c5bd813e983eb07e9836fea96ddadb9528892febcf", "situation": "You are a team lead. In a team meeting this morning a colleague said, in front of six people: \"To be fair, the project went to you because you know the vice-president socially. The rest of us didn''t really get a look in.\"\n\nWhat the record shows: the project was awarded through a written proposal process; three people evaluated the proposals against published criteria; four proposals were submitted; the evaluation record names all three evaluators and the vice-president is not among them; you do know the vice-president socially, from industry events.", "reveals": [{"code": "R1", "text": "What do you say in the meeting, word for word?", "role": "Opening"}, {"code": "R2", "text": "Who are you saying it to?", "role": "Information"}, {"code": "R3", "text": "Another colleague asks: \"So how were they actually evaluated?\" What do you say?", "role": "Information"}, {"code": "R4", "text": "What, if anything, goes out after the meeting, to whom, and by when?", "role": "Information"}, {"code": "R5", "text": "The next day the vice-president says: \"I hear my name came up. What was said?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items, one of which concedes the social acquaintance"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R1 asks for the words"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A specific question at R3"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "NOT SERVED", "basis": "The situation lists no unconfirmed item"}, {"question": "Q-D4-05b", "state": "NOT SERVED", "basis": "The source designates no unconfirmed_items item, so the bound question cannot be offered"}, {"question": "Q-D4-06", "state": "DIRECT", "basis": "THE PRIMARY ELEMENT"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "The source designates no available_channels item, so the bound question cannot be offered"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R4 asks about a further communication"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at R5"}], "material_map": [{"Item": "MI1", "Item text": "that the award followed a written proposal process", "Where the participant meets it": "The situation", "Quoted text": "awarded through a written proposal process; three people evaluated the proposals against published criteria; four proposals"}, {"Item": "MI2", "Item text": "that three named evaluators assessed four proposals against published criteria", "Where the participant meets it": "The situation", "Quoted text": "proposal process; three people evaluated the proposals against published criteria; four proposals were submitted; the evaluation record names all three evaluators"}, {"Item": "MI3", "Item text": "that the vice-president was not an evaluator", "Where the participant meets it": "The situation", "Quoted text": "the vice-president is not among them"}, {"Item": "MI4", "Item text": "that the participant does know the vice-president socially", "Where the participant meets it": "The situation", "Quoted text": "do know the vice-president socially"}], "source_sheet": {"d4_situation_class": "SC-D4-3", "workplace_demand": "Communicating what a record contains where an attribution contradicts it.", "relevant_conduct": "Who was addressed; which designated items the statement contained; the order; whether the question at R3 was answered with designated contents; whether the social acquaintance was stated; the further communication; the answer at R5.", "irrelevant_conduct": "How the participant felt; team dynamics; whether the colleague should have said it.", "stated_standard": "\"three people evaluated the proposals against published criteria\" and \"the vice-president is not among them.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"three people evaluated the proposals against published criteria\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That defending oneself was required; that raising it privately would have been better; anything about composure.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "recipient_roles": [{"id": "RR1", "text": "the colleague who spoke"}, {"id": "RR2", "text": "the room"}, {"id": "RR3", "text": "the vice-president"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the award followed a written proposal process"}, {"id": "MI2", "text": "that three named evaluators assessed four proposals against published criteria"}, {"id": "MI3", "text": "that the vice-president was not an evaluator"}, {"id": "MI4", "text": "that the participant does know the vice-president socially"}], "designated_answer_contents": [{"id": "AC1", "text": "the three evaluators and the published criteria"}, {"id": "AC2", "text": "that four proposals were submitted"}], "unconfirmed_items": [], "available_channels": [], "designated_points": "R1 and R3 in the meeting; R4 after it.", "question_put": "\"So how were they actually evaluated?\" Exact text at R3.", "contradicted_attribution": "The colleague attributes the award to social acquaintance; the record holds a three-evaluator written process. Both texts at the situation.", "adverse_effect_party": null, "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "R5", "list_note": null, "source_note": "Re-framed from the library scenario: The library scenario centers on a rumour reaching the participant through a confidant, and on its effect on team dynamics. BOTH ARE REMOVED. What remains is an attribution contradicted by a record, which is what D4 observes. No question here observes how the participant feels about the attribution or how the team responded to it.", "situation_class_label": "A statement attributed to the person that the record contradicts", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D4-S1-006", "stage_code": "S1", "source_version_hash": "999f00187ac7a3e96c6246c5bd813e983eb07e9836fea96ddadb9528892febcf", "serving_eligible": false, "verbatim": "You are a team lead. In a team meeting this morning a colleague said, in front of six people: \"To be fair, the project went to you because you know the vice-president socially. The rest of us didn''t really get a look in.\"\n\nWhat the record shows: the project was awarded through a written proposal process; three people evaluated the proposals against published criteria; four proposals were submitted; the evaluation record names all three evaluators and the vice-president is not among them; you do know the vice-president socially, from industry events."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S1-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S1-008', 'source'::public.t3a_content_family, 'THE QUESTION FROM THE FLOOR', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE QUESTION FROM THE FLOOR", "source_digest": "d7c2dfb05de8a0821affba1153a8321d04eef3786789f28d913dd43b31f1fd64", "situation": "You are at a monthly all-hands meeting with about two hundred people. The chief executive is presenting quarterly results and calls on you without warning:\n\n\"You''re on the client implementation, right? We''ve been getting some noise from the client. Can you give everyone a quick update on where that project stands?\"\n\nWhat the record shows: the project is ten days behind schedule; the delay was caused by a vendor issue that is now resolved; the revised timeline is on track; the client''s complaint was about the delay and has been answered; and the final acceptance date has not yet been confirmed by the client.", "reveals": [{"code": "R1", "text": "What do you say, word for word?", "role": "Opening"}, {"code": "R2", "text": "Who are you addressing?", "role": "Information"}, {"code": "R3", "text": "The chief executive follows up: \"And when does it land?\" What do you say?", "role": "Information"}, {"code": "R4", "text": "What, if anything, goes out after the meeting, to whom, and by when?", "role": "Information"}, {"code": "R5", "text": "Afterwards your supervisor says: \"You told two hundred people it was on track. On track to what date?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles, one of them an audience of two hundred"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R1 asks for the words. ORDER MATTERS MOST HERE — whether the delay or the recovery came first is the fact recorded, never whether it was the better order"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A closed question at R3"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The acceptance date is recorded as unconfirmed"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "The source designates no available_channels item, so the bound question cannot be offered"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R4 asks about a further communication"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at R5"}], "material_map": [{"Item": "MI1", "Item text": "that the project is ten days behind", "Where the participant meets it": "The situation", "Quoted text": "project is ten days behind"}, {"Item": "MI2", "Item text": "that the cause was a vendor issue now resolved", "Where the participant meets it": "The situation", "Quoted text": "vendor issue that is now resolved"}, {"Item": "MI3", "Item text": "that the revised timeline is being met", "Where the participant meets it": "The situation", "Quoted text": "revised timeline is on"}, {"Item": "MI4", "Item text": "that the client''s complaint has been answered", "Where the participant meets it": "The situation", "Quoted text": "client''s complaint was about the delay and has been answered; and the final acceptance date has not yet been confirmed by the"}, {"Item": "UC1", "Item text": "the final acceptance date", "Where the participant meets it": "The situation", "Quoted text": "final acceptance date has"}], "source_sheet": {"d4_situation_class": "SC-D4-1", "workplace_demand": "Giving a position to a large audience with no time to prepare it.", "relevant_conduct": "Who was addressed; which designated items were contained; the order; whether the question at R3 was answered; whether the unconfirmed acceptance date was identified as unconfirmed; the further communication; the answer at R5.", "irrelevant_conduct": "Whether the participant seemed confident in front of two hundred people; the chief executive''s framing; the vendor.", "stated_standard": "\"the final acceptance date has not yet been confirmed by the client.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"the final acceptance date has not yet been confirmed by the client\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That a brief answer is better; that mentioning the delay was required or unwise; anything about public speaking.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "recipient_roles": [{"id": "RR1", "text": "the chief executive, who asked"}, {"id": "RR2", "text": "the two hundred people in the room"}, {"id": "RR3", "text": "the participant''s supervisor"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the project is ten days behind"}, {"id": "MI2", "text": "that the cause was a vendor issue now resolved"}, {"id": "MI3", "text": "that the revised timeline is being met"}, {"id": "MI4", "text": "that the client''s complaint has been answered"}], "designated_answer_contents": [{"id": "AC1", "text": "the revised timeline date"}, {"id": "AC2", "text": "that the client has not yet confirmed final acceptance"}], "unconfirmed_items": [{"id": "UC1", "text": "the final acceptance date"}], "available_channels": [], "designated_points": "R1 and R3 in the room.", "question_put": "\"And when does it land?\" Exact text at R3.", "contradicted_attribution": null, "adverse_effect_party": null, "escalation_state": "The matter is being discussed in front of two hundred people who were not party to it.", "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "R5", "list_note": null, "source_note": null, "situation_class_label": "A question put in front of others before an answer can be prepared", "observation_mode_label": "written_response", "min_seconds": 300, "max_seconds": 1200}, "source_identifier": "SRC-D4-S1-008", "stage_code": "S1", "source_version_hash": "d7c2dfb05de8a0821affba1153a8321d04eef3786789f28d913dd43b31f1fd64", "serving_eligible": false, "verbatim": "You are at a monthly all-hands meeting with about two hundred people. The chief executive is presenting quarterly results and calls on you without warning:\n\n\"You''re on the client implementation, right? We''ve been getting some noise from the client. Can you give everyone a quick update on where that project stands?\"\n\nWhat the record shows: the project is ten days behind schedule; the delay was caused by a vendor issue that is now resolved; the revised timeline is on track; the client''s complaint was about the delay and has been answered; and the final acceptance date has not yet been confirmed by the client."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S1-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S1-009', 'source'::public.t3a_content_family, 'THE THREAD THAT GREW', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE THREAD THAT GREW", "source_digest": "fa2a0fff83bf276729ae444fa052993cc744ebff1e111bfb8db4fe5d83ab173c", "situation": "Last Thursday you sent a one-line email to a colleague asking about the timeline for a deliverable. They replied and added their manager. The manager replied and added two directors. One director replied to all, criticising the original timeline. The other defended it and copied the vice-president.\n\nIt is Monday. The thread has fourteen people copied and twenty-two messages, and has moved on to project management processes, resource allocation and team accountability. Your name is on the original message.\n\nThe latest reply, from one of the directors, reads: \"This thread is a perfect example of why nothing moves here. Who actually owns this?\"\n\nWhat the record shows: your original message asked one question about one date; the deliverable date was confirmed by the delivery team on Friday; none of the process questions in the thread was raised by you.", "reveals": [{"code": "R1", "text": "What do you send, word for word?", "role": "Opening"}, {"code": "R2", "text": "Who is it going to — the whole thread, or some of it?", "role": "Information"}, {"code": "R3", "text": "The director replies to you only: \"Fine. So what is the date?\" What do you say?", "role": "Information"}, {"code": "R4", "text": "Is there anything further, to whom, and by when?", "role": "Information"}, {"code": "R5", "text": "The vice-president asks: \"You started this thread. What did you originally ask?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "THE PRIMARY ELEMENT. Whether the recipient set was narrowed is the situation"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Three designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R1 asks for the words"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A closed question with one designated content"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "NOT SERVED", "basis": "The situation lists no unconfirmed item"}, {"question": "Q-D4-05b", "state": "NOT SERVED", "basis": "The source designates no unconfirmed_items item, so the bound question cannot be offered"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "The source designates no available_channels item, so the bound question cannot be offered"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R4 asks about a further communication"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at R5"}], "material_map": [{"Item": "MI1", "Item text": "the confirmed deliverable date", "Where the participant meets it": "The situation", "Quoted text": "date; the deliverable date was confirmed"}, {"Item": "MI2", "Item text": "that the original question was about that one date", "Where the participant meets it": "The situation", "Quoted text": "original message asked one question about one date; the deliverable date was confirmed by the delivery team on Friday; none of the"}, {"Item": "MI3", "Item text": "that the process questions in the thread were raised by others", "Where the participant meets it": "The situation", "Quoted text": "date; the deliverable date was confirmed by the delivery team on Friday; none of the process questions in the thread was raised"}], "source_sheet": {"d4_situation_class": "SC-D4-5", "workplace_demand": "Communicating into an exchange that has moved beyond the people who began it.", "relevant_conduct": "Who was addressed and whether the recipient set was narrowed; which designated items were contained; the order; whether the question at R3 was answered; whether anything not on the record was identified as such; the further communication; the answer at R5.", "irrelevant_conduct": "Who escalated the thread; whether the directors were reasonable; whether the participant should have replied at all.", "stated_standard": "\"your original message asked one question about one date.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"your original message asked one question about one date\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That narrowing the recipients is better than replying to all; that silence would have been wiser; anything about political judgment.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "recipient_roles": [{"id": "RR1", "text": "the director who asked who owns it"}, {"id": "RR2", "text": "the full thread of fourteen"}, {"id": "RR3", "text": "the original colleague only"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the confirmed deliverable date"}, {"id": "MI2", "text": "that the original question was about that one date"}, {"id": "MI3", "text": "that the process questions in the thread were raised by others"}], "designated_answer_contents": [{"id": "AC1", "text": "the deliverable date confirmed by the delivery team on Friday"}], "unconfirmed_items": [], "available_channels": [], "designated_points": "R1 and R3.", "question_put": "\"Fine. So what is the date?\" Exact text at R3.", "contradicted_attribution": null, "adverse_effect_party": null, "escalation_state": "The exchange has passed from two people to fourteen, and the subject has moved from one date to three process topics.", "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "R5", "list_note": null, "source_note": "contradicted_attribution: The director''s remark characterises the thread, not the participant''s words.", "situation_class_label": "A communication that has passed beyond the people who began it", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D4-S1-009", "stage_code": "S1", "source_version_hash": "fa2a0fff83bf276729ae444fa052993cc744ebff1e111bfb8db4fe5d83ab173c", "serving_eligible": false, "verbatim": "Last Thursday you sent a one-line email to a colleague asking about the timeline for a deliverable. They replied and added their manager. The manager replied and added two directors. One director replied to all, criticising the original timeline. The other defended it and copied the vice-president.\n\nIt is Monday. The thread has fourteen people copied and twenty-two messages, and has moved on to project management processes, resource allocation and team accountability. Your name is on the original message.\n\nThe latest reply, from one of the directors, reads: \"This thread is a perfect example of why nothing moves here. Who actually owns this?\"\n\nWhat the record shows: your original message asked one question about one date; the deliverable date was confirmed by the delivery team on Friday; none of the process questions in the thread was raised by you."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S1-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S1-010', 'source'::public.t3a_content_family, 'THE REQUEST THAT CANNOT BE GRANTED', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE REQUEST THAT CANNOT BE GRANTED", "source_digest": "0b2115927351e82bccb192860c1c4df2e8bea421da4165f65664d22aaa8cf54d", "situation": "You are a project coordinator. A colleague with fifteen years at the company asks: \"I need you to add me to the project team. I know it''s already set, but I want experience on a strategic account and this is the right one. I''ve already told my manager I''d be joining, so it''s basically a done deal. Can you add me to the plan and send me the invites?\"\n\nWhat the record shows: the team was selected against a published skills matrix and the colleague''s expertise is not on it; adding a member at this stage requires the project manager''s written approval; the project manager is contactable today; and nobody has told the colleague''s manager anything from your side.", "reveals": [{"code": "R1", "text": "What do you say to the colleague, word for word?", "role": "Opening"}, {"code": "R2", "text": "Who else, if anyone, do you communicate with, and what do you say?", "role": "Information"}, {"code": "R3", "text": "The colleague asks: \"So are you adding me or not?\" What do you say?", "role": "Information"}, {"code": "R4", "text": "What goes out after this conversation, to whom, and by when?", "role": "Information"}, {"code": "R5", "text": "Two days later the project manager says: \"I hear you told someone it was possible. What did you actually say?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R1 asks for the words"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A closed question at R3"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The approval outcome is recorded as unasked"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "The source designates no available_channels item, so the bound question cannot be offered"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R4 asks about a further communication"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at R5"}], "material_map": [{"Item": "MI1", "Item text": "that the team was selected against a published skills matrix", "Where the participant meets it": "The situation", "Quoted text": "team was selected against a published skills matrix"}, {"Item": "MI2", "Item text": "that adding a member requires the project manager''s written approval", "Where the participant meets it": "The situation", "Quoted text": "adding a member at this stage requires the project manager''s written approval; the project manager is contactable today; and nobody has told"}, {"Item": "MI3", "Item text": "that no approval has been sought", "Where the participant meets it": "The situation", "Quoted text": "requires the project manager''s written approval"}, {"Item": "MI4", "Item text": "that the participant cannot add anyone to the plan", "Where the participant meets it": "The situation", "Quoted text": "add me to the plan"}, {"Item": "UC1", "Item text": "whether the project manager would approve, which has not been asked", "Where the participant meets it": "Reveal R5", "Quoted text": "project manager says: \"I"}], "source_sheet": {"d4_situation_class": "SC-D4-6", "workplace_demand": "Communicating that a request cannot be granted to someone who has already told others it will be.", "relevant_conduct": "Who was addressed; which designated items were contained; the order; whether the question at R3 was answered; whether the approval position was identified as not yet sought; the further communication; the answer at R5.", "irrelevant_conduct": "The colleague''s seniority; whether saying no was hard; whether the participant was diplomatic.", "stated_standard": "\"adding a member at this stage requires the project manager''s written approval.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"adding a member at this stage requires the project manager''s written approval\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That a direct refusal is better than deferring to the project manager; that the participant should protect the colleague from embarrassment; anything about firmness.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "recipient_roles": [{"id": "RR1", "text": "the colleague making the request"}, {"id": "RR2", "text": "the project manager"}, {"id": "RR3", "text": "the colleague''s manager"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the team was selected against a published skills matrix"}, {"id": "MI2", "text": "that adding a member requires the project manager''s written approval"}, {"id": "MI3", "text": "that no approval has been sought"}, {"id": "MI4", "text": "that the participant cannot add anyone to the plan"}], "designated_answer_contents": [{"id": "AC1", "text": "that the participant is not adding them"}, {"id": "AC2", "text": "who decides, and by when they could answer"}], "unconfirmed_items": [{"id": "UC1", "text": "whether the project manager would approve, which has not been asked"}], "available_channels": [], "designated_points": "R1 and R3 in the conversation; R4 after it.", "question_put": "\"So are you adding me or not?\" Exact text at R3.", "contradicted_attribution": null, "adverse_effect_party": "The colleague, who has already told their manager they are joining.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": "\"Can you add me to the plan and send me the invites?\" Exact text at the situation.", "statement_test_point": "R5", "list_note": null, "source_note": null, "situation_class_label": "A request that cannot be granted as asked", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D4-S1-010", "stage_code": "S1", "source_version_hash": "0b2115927351e82bccb192860c1c4df2e8bea421da4165f65664d22aaa8cf54d", "serving_eligible": false, "verbatim": "You are a project coordinator. A colleague with fifteen years at the company asks: \"I need you to add me to the project team. I know it''s already set, but I want experience on a strategic account and this is the right one. I''ve already told my manager I''d be joining, so it''s basically a done deal. Can you add me to the plan and send me the invites?\"\n\nWhat the record shows: the team was selected against a published skills matrix and the colleague''s expertise is not on it; adding a member at this stage requires the project manager''s written approval; the project manager is contactable today; and nobody has told the colleague''s manager anything from your side."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S1-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S2-001', 'source'::public.t3a_content_family, 'THE CALL ABOUT THE OUTAGE', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE CALL ABOUT THE OUTAGE", "source_digest": "de3f877f1cadc95904bfba432ef1526bc2c95f3880032469f65380ae2fcaec68", "mentor_brief": "The mentor reads the scripted lines of the operations manager. THE MENTOR''S DELIVERY DOES NOT CHANGE WHATEVER THE PARTICIPANT SAYS. No escalation, no repetition, no expressive reaction, no unscripted follow-up.", "participant_pre_brief": "You are a client services representative. A long-standing client''s system went down during a critical processing window and they believe your company is responsible. What the record shows: the outage began at 09:12 and ran for fifty-one minutes; the root cause is not yet established; a third-party rate limit and an internal configuration change are both under investigation; your engineering team has committed to a written cause statement within three business days; and no compensation position has been set. The client''s operations manager is on the line.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Our system was down through our processing window this morning. Fifty-one minutes. I need to understand what happened. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What happened to our system this morning?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What caused it?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What am I getting from you, and when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the cause is known. Is it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles, one on the call"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Multiple items across four beats, so an order is recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4 with two designated contents"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "TWO unconfirmed items — the only Stage 2 source with more than one"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "The call is a channel used in session. CH-02 is NOT eligible — a statement to follow is an intention"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what is coming and when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "MI1", "Item text": "that the outage ran fifty-one minutes from 09:12", "Where the participant meets it": "The pre-brief", "Quoted text": "outage began at 09:12 and ran for fifty-one minutes"}, {"Item": "MI2", "Item text": "that the root cause is not yet established", "Where the participant meets it": "The pre-brief", "Quoted text": "root cause is not yet established; a third-party rate limit and an internal configuration change are both under investigation; your engineering team"}, {"Item": "MI3", "Item text": "that a written cause statement follows within three business days", "Where the participant meets it": "The pre-brief", "Quoted text": "an internal configuration change are both under investigation; your engineering team has committed to a written cause statement within three business days"}, {"Item": "MI4", "Item text": "that no compensation position has been set", "Where the participant meets it": "The pre-brief", "Quoted text": "compensation position has been set"}, {"Item": "UC1", "Item text": "the third-party rate limit as a cause", "Where the participant meets it": "The pre-brief", "Quoted text": "cause is not yet established; a third-party rate limit and an internal configuration change are both under investigation; your engineering team has"}, {"Item": "UC2", "Item text": "the internal configuration change as a cause", "Where the participant meets it": "The pre-brief", "Quoted text": "cause is not yet established; a third-party rate limit and an internal configuration change are both under investigation; your engineering team has"}], "source_sheet": {"d4_situation_class": "SC-D4-2", "workplace_demand": "Communicating with an adversely affected party where the cause is not yet established.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order; whether the question at B4 was answered with designated contents; whether the two candidate causes were identified as unconfirmed; the further communication stated; the answer at B6.", "irrelevant_conduct": "The client''s volume or manner; whether the participant sounded apologetic or composed; who is at fault, WHICH IS A D2 MATTER.", "stated_standard": "\"a written cause statement within three business days.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"a written cause statement within three business days\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only. Accommodations changing channel or pause window are recorded and set `timing_not_comparable`.", "unsupported_inferences": "That apologising was required; that naming a candidate cause was unwise; anything about handling an angry caller.", "compatibility_class": "S2-SEVEN-BEAT", "recipient_roles": [{"id": "RR1", "text": "the client''s operations manager on the call"}, {"id": "RR2", "text": "the participant''s engineering team"}, {"id": "RR3", "text": "the participant''s supervisor"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the outage ran fifty-one minutes from 09:12"}, {"id": "MI2", "text": "that the root cause is not yet established"}, {"id": "MI3", "text": "that a written cause statement follows within three business days"}, {"id": "MI4", "text": "that no compensation position has been set"}], "designated_answer_contents": [{"id": "AC1", "text": "that the cause is under investigation and not established"}, {"id": "AC2", "text": "the two lines of investigation, identified as candidates"}], "unconfirmed_items": [{"id": "UC1", "text": "the third-party rate limit as a cause"}, {"id": "UC2", "text": "the internal configuration change as a cause"}], "available_channels": [{"id": "CH1", "text": "the live call"}], "designated_points": "B3 to B6 on the call; the written statement within three business days.", "question_put": "\"What caused it?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": "The client''s operations manager.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "B6", "list_note": "Not selectable in available_channels: a written statement to follow.", "source_note": null, "situation_class_label": "Information that will adversely affect the party who receives it", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D4-S2-001", "stage_code": "S2", "source_version_hash": "de3f877f1cadc95904bfba432ef1526bc2c95f3880032469f65380ae2fcaec68", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S2-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S2-004', 'source'::public.t3a_content_family, 'THE POLICY THE ROOM DID NOT CHOOSE', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE POLICY THE ROOM DID NOT CHOOSE", "source_digest": "babadcf403c0336480e540a1f76c008880a8d7d8d8b37d88c50aaa5fd9d9e29f", "mentor_brief": "The mentor reads the scripted lines of one employee in the room, and nothing else. THE MENTOR DOES NOT ESCALATE, does not add a second objection, and does not react to whatever the participant says.", "participant_pre_brief": "You coordinate people operations. Management has changed the attendance policy: from next month, four days a week on site, up from two. You did not make the decision and you have been asked to present it to a department of fifteen. Most of them arranged childcare, commutes and in some cases where they live around the two-day policy. What the record shows: the change takes effect on the first of next month; there is a stated exception process for documented accessibility and caregiving needs, with a two-week application window; no individual exceptions have been decided; and the rationale given to you in writing is a single line about collaboration.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Thanks everyone. I understand there is an announcement about attendance. I will hand over.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "I moved forty-five minutes out because of the two-day policy. What am I supposed to do?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Is there any way round this for people in that position?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What are we getting in writing, and when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said exceptions are available. Have any been agreed?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "A room and an individual within it are both addressable"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order is recoverable across four beats"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The exception outcome is recorded as undecided"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "The meeting is a channel used in session"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what comes in writing and when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at B6"}], "material_map": [{"Item": "MI1", "Item text": "the effective date, the first of next month", "Where the participant meets it": "The pre-brief", "Quoted text": "first of next month"}, {"Item": "MI2", "Item text": "that an exception process exists for documented accessibility and caregiving needs", "Where the participant meets it": "The pre-brief", "Quoted text": "exception process for documented accessibility and caregiving needs, with a two-week application window; no individual exceptions"}, {"Item": "MI3", "Item text": "the two-week application window", "Where the participant meets it": "The pre-brief", "Quoted text": "application window; no individual"}, {"Item": "MI4", "Item text": "that the participant did not make the decision", "Where the participant meets it": "The pre-brief", "Quoted text": "did not make the decision"}, {"Item": "UC1", "Item text": "whether any individual exception will be granted", "Where the participant meets it": "The pre-brief", "Quoted text": "exception process for documented accessibility and caregiving needs, with a two-week application window; no individual exceptions"}], "source_sheet": {"d4_situation_class": "SC-D4-2", "workplace_demand": "Communicating a decision the participant did not make to people it disadvantages.", "relevant_conduct": "Who was addressed; which designated items were contained; the order; whether the question at B4 was answered; whether the undecided exceptions were identified as undecided; the further communication; the answer at B6.", "irrelevant_conduct": "Whether the policy is reasonable; whether the participant seemed sympathetic; management''s rationale.", "stated_standard": "\"a stated exception process for documented accessibility and caregiving needs, with a two-week application window.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"a stated exception process for documented accessibility and caregiving needs, with a two-week application window\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That distancing from the decision was right or wrong; that the participant should advocate for the room; anything about warmth.", "compatibility_class": "S2-SEVEN-BEAT", "recipient_roles": [{"id": "RR1", "text": "the department of fifteen"}, {"id": "RR2", "text": "the employee who spoke"}, {"id": "RR3", "text": "management, who made the decision"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the effective date, the first of next month"}, {"id": "MI2", "text": "that an exception process exists for documented accessibility and caregiving needs"}, {"id": "MI3", "text": "the two-week application window"}, {"id": "MI4", "text": "that the participant did not make the decision"}], "designated_answer_contents": [{"id": "AC1", "text": "the exception process and its window"}, {"id": "AC2", "text": "that no exception has yet been decided"}], "unconfirmed_items": [{"id": "UC1", "text": "whether any individual exception will be granted"}], "available_channels": [{"id": "CH1", "text": "the department meeting"}], "designated_points": "B3 to B6 in the meeting.", "question_put": "\"Is there any way round this for people in that position?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": "The department.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": "The employee asks for a way round the policy, which the participant cannot grant. Exact text at B4.", "statement_test_point": "B6", "list_note": "Not selectable in available_channels: a written follow-up to the department.", "source_note": null, "situation_class_label": "Information that will adversely affect the party who receives it", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D4-S2-004", "stage_code": "S2", "source_version_hash": "babadcf403c0336480e540a1f76c008880a8d7d8d8b37d88c50aaa5fd9d9e29f", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S2-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S2-006', 'source'::public.t3a_content_family, 'THE PROPOSAL THAT KEEPS BEING INTERRUPTED', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE PROPOSAL THAT KEEPS BEING INTERRUPTED", "source_digest": "3c1b3ecb3387f5ad183bbddfbe96eee555eb3148dd163e58a0bf1cdd6bed4c30", "mentor_brief": "The mentor reads the scripted lines of the operations vice-president, at the scripted beats and no others.", "participant_pre_brief": "You are presenting a project proposal to a group of senior leaders. What the record shows: the proposal has a modelled return of eleven per cent over eighteen months; the model rests on two assumptions, adoption rate and license cost, both of which are stated in the appendix as estimates; the implementation timeline is fourteen weeks; and two comparable proposals in the last three years did not proceed, for reasons not recorded.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have fifteen minutes. Go ahead.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Before you go on — what''s the return on this?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "I''ve seen proposals like this before and they never work. What makes yours different?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What are you sending me after this, and by when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said eleven per cent. Is that modelled or actual?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Two addressable roles only — the narrowest recipient set in the bank"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Three designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "THE ORDER IS THE SITUATION — the question arrives before the explanation, so what came first is the fact recorded"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A challenge question at B4 with two designated contents"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "Two assumptions recorded as estimates"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "The meeting is a channel used in session"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what is sent and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at B6"}], "material_map": [{"Item": "MI1", "Item text": "the modelled return of eleven per cent over eighteen months", "Where the participant meets it": "The pre-brief", "Quoted text": "modelled return of eleven per cent over eighteen months"}, {"Item": "MI2", "Item text": "that the model rests on two stated assumptions", "Where the participant meets it": "The pre-brief", "Quoted text": "model rests on two assumptions, adoption rate and license cost, both of which are stated"}, {"Item": "MI3", "Item text": "the fourteen-week implementation timeline", "Where the participant meets it": "The pre-brief", "Quoted text": "implementation timeline is fourteen weeks"}, {"Item": "UC1", "Item text": "the adoption rate assumption", "Where the participant meets it": "The pre-brief", "Quoted text": "assumptions, adoption rate and"}, {"Item": "UC2", "Item text": "the license cost assumption", "Where the participant meets it": "The pre-brief", "Quoted text": "assumptions, adoption rate and license cost"}], "source_sheet": {"d4_situation_class": "SC-D4-1", "workplace_demand": "Giving a position when the question arrives before the explanation does.", "relevant_conduct": "Who was addressed; which designated items were contained; the order; whether the question at B4 was answered with designated contents; whether the two assumptions were identified as estimates; the further communication; the answer at B6.", "irrelevant_conduct": "Whether the participant held the floor; whether the interruptions were handled well; the vice-president''s manner.", "stated_standard": "\"both of which are stated in the appendix as estimates.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"both of which are stated in the appendix as estimates\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That the participant should have pushed back on the interruption; that a short answer is better; anything about presence.", "compatibility_class": "S2-SEVEN-BEAT", "recipient_roles": [{"id": "RR1", "text": "the operations vice-president who asked"}, {"id": "RR2", "text": "the group of senior leaders"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the modelled return of eleven per cent over eighteen months"}, {"id": "MI2", "text": "that the model rests on two stated assumptions"}, {"id": "MI3", "text": "the fourteen-week implementation timeline"}], "designated_answer_contents": [{"id": "AC1", "text": "the two assumptions and that they are estimates"}, {"id": "AC2", "text": "the fourteen-week timeline"}], "unconfirmed_items": [{"id": "UC1", "text": "the adoption rate assumption"}, {"id": "UC2", "text": "the license cost assumption"}], "available_channels": [{"id": "CH1", "text": "the meeting itself"}], "designated_points": "B3 to B6.", "question_put": "\"What makes yours different?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": null, "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "B6", "list_note": "Not selectable in available_channels: a follow-up pack to the vice-president.", "source_note": null, "situation_class_label": "A question put in front of others before an answer can be prepared", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D4-S2-006", "stage_code": "S2", "source_version_hash": "3c1b3ecb3387f5ad183bbddfbe96eee555eb3148dd163e58a0bf1cdd6bed4c30", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S2-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S2-007', 'source'::public.t3a_content_family, 'THE SENTENCE READ BACK WITHOUT ITS SECOND HALF', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE SENTENCE READ BACK WITHOUT ITS SECOND HALF", "source_digest": "deffe4723bab4c5ba5a51070a4bc7572375550b1e3f199c8e452f51a866ab4d7", "mentor_brief": "The mentor reads the scripted lines of the colleague, once each, at the scripted beats. The mentor does not defend the quotation, does not repeat it, and does not react to whatever the participant says.", "participant_pre_brief": "You are in a team meeting with eight colleagues. What the record shows: last week you sent an email reading \"The current process has gaps that are creating bottlenecks, and the team isn''t delivering at the pace the client expects. I think we should discuss improvements at our next meeting.\" The email is in the thread and has not been edited.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Before we move on — I want to raise something. And I quote from your email: ''The current process is broken and the team isn''t delivering.'' So you think we''re all underperforming. I''ll let you respond.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Is that not what you meant?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C6", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "So what did the email actually say?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What are you circulating after this, and to whom?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you''re saying I misquoted you. Is that it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles, including the thread itself"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items, all drawn from the record text"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order recoverable across four beats"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4 with one designated content"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "NOT SERVED", "basis": "The situation lists no unconfirmed item"}, {"question": "Q-D4-05b", "state": "NOT SERVED", "basis": "The source designates no unconfirmed_items item, so the bound question cannot be offered"}, {"question": "Q-D4-06", "state": "DIRECT", "basis": "THE PRIMARY ELEMENT AND THE CLEAREST INSTANCE IN THE ESTATE"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "The meeting is a channel used in session"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what is circulated and to whom"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at B6, and it puts an interpretation of the participant''s own position back to them"}], "material_map": [{"Item": "MI1", "Item text": "that the email says the process has gaps creating bottlenecks, not that it is broken", "Where the participant meets it": "The pre-brief", "Quoted text": "email reading \"The current process has gaps that are creating bottlenecks"}, {"Item": "MI2", "Item text": "that the email refers to the pace the client expects", "Where the participant meets it": "The pre-brief", "Quoted text": "email reading \"The current process has gaps that are creating bottlenecks, and the team isn''t delivering at the pace the client expects"}, {"Item": "MI3", "Item text": "that the email proposes discussing improvements at the next meeting", "Where the participant meets it": "The pre-brief", "Quoted text": "improvements at our next meeting.\""}, {"Item": "MI4", "Item text": "that the email is in the thread unedited", "Where the participant meets it": "The pre-brief", "Quoted text": "email is in the thread"}], "source_sheet": {"d4_situation_class": "SC-D4-3", "workplace_demand": "Communicating what a record contains where a quotation of the participant has been stripped of its qualifiers.", "relevant_conduct": "Who was addressed; which designated items were contained; the order; whether the question at B4 was answered with the record text; whether anything not in the record was identified as such; the further communication; the answer at B6.", "irrelevant_conduct": "Whether the colleague acted in bad faith; whether the participant was firm or conciliatory; the room''s reaction.", "stated_standard": "The exact email text at the pre-brief. IT IS THE RECORD and every determination about the attribution is compared to it.", "stated_standard_source_quote_or_location": "\"email reading \"The current process has gaps that are creating bottlenecks\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That correcting the record publicly was required or unwise; that letting it stand would be weakness; anything about assertiveness.", "compatibility_class": "S2-SEVEN-BEAT", "recipient_roles": [{"id": "RR1", "text": "the colleague who quoted the email"}, {"id": "RR2", "text": "the eight colleagues in the room"}, {"id": "RR3", "text": "the original email thread"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the email says the process has gaps creating bottlenecks, not that it is broken"}, {"id": "MI2", "text": "that the email refers to the pace the client expects"}, {"id": "MI3", "text": "that the email proposes discussing improvements at the next meeting"}, {"id": "MI4", "text": "that the email is in the thread unedited"}], "designated_answer_contents": [{"id": "AC1", "text": "the email text as the record holds it"}], "unconfirmed_items": [], "available_channels": [{"id": "CH1", "text": "the meeting itself"}], "designated_points": "B3 to B6 in the meeting.", "question_put": "\"So what did the email actually say?\" Exact text at B4.", "contradicted_attribution": "The colleague quotes \"The current process is broken and the team isn''t delivering\"; the record holds the longer sentence with its qualifiers. Both texts are in the source.", "adverse_effect_party": null, "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "B6", "list_note": "Not selectable in available_channels: recirculating the original email to the thread.", "source_note": null, "situation_class_label": "A statement attributed to the person that the record contradicts", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D4-S2-007", "stage_code": "S2", "source_version_hash": "deffe4723bab4c5ba5a51070a4bc7572375550b1e3f199c8e452f51a866ab4d7", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S2-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S2-008', 'source'::public.t3a_content_family, 'THE PROCEDURE WITH NO WRITTEN FORM', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE PROCEDURE WITH NO WRITTEN FORM", "source_digest": "1df4ed6efeff8774b5ce28a09dc381fab3294a4997b8102234d45271588df6e3", "mentor_brief": "The mentor reads the scripted lines of the shift supervisor. The mentor does not comment on how anything is explained, does not ask the participant to simplify, and does not react to whatever is said. NO MENTOR CUE IN THIS SOURCE REFERS TO CLARITY, PACE OR LANGUAGE.", "participant_pre_brief": "You coordinate safety on a production site. A new team member starts on the floor tomorrow and must be briefed on the press procedure before they do. What the record shows: the procedure has three parts — the isolation sequence, the emergency stop, and the spill response; no written form of it exists for this machine, because it was installed six weeks ago and the documentation is still with the manufacturer; the standard induction pack covers the older machines only; site rules require that a briefing on an undocumented procedure is followed by a written note within one working day; and the manufacturer''s documentation is expected next week but is not confirmed.", "script": [{"beat": "B1", "type": "SAY", "spoken": "The new starter is on the floor at six tomorrow. They need the press procedure before that. I will let you take me through it.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "How are you briefing them tomorrow?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "There''s no written procedure for that machine. What are you giving them?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What''s going in writing, to whom, and by when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the manufacturer''s documentation is coming. Is that confirmed?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items, three of them procedure parts"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Three procedure parts make the order recoverable and meaningful"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The documentation date is recorded as unconfirmed"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "TWO CHANNELS ARE PERFORMABLE IN SESSION — the only source in the bank where the channel element has a genuine choice"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "CH-03 is NOT eligible"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what goes in writing, to whom and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at B6"}], "material_map": [{"Item": "MI1", "Item text": "the isolation sequence", "Where the participant meets it": "The pre-brief", "Quoted text": "isolation sequence, the emergency"}, {"Item": "MI2", "Item text": "the emergency stop", "Where the participant meets it": "The pre-brief", "Quoted text": "emergency stop, and the"}, {"Item": "MI3", "Item text": "the spill response", "Where the participant meets it": "The pre-brief", "Quoted text": "spill response; no written"}, {"Item": "MI4", "Item text": "that no written form exists for this machine", "Where the participant meets it": "The pre-brief", "Quoted text": "written form of it exists for this machine, because it was installed six weeks ago and the documentation is still with the"}, {"Item": "UC1", "Item text": "the arrival date of the manufacturer''s documentation", "Where the participant meets it": "Beat B6", "Quoted text": "manufacturer''s documentation is coming"}], "source_sheet": {"d4_situation_class": "SC-D4-7", "workplace_demand": "Communicating a procedure for which no standard written form exists.", "relevant_conduct": "Who was addressed; which of the three procedure parts the communication contained; the order; whether the question at B4 was answered; whether the unconfirmed documentation date was identified as unconfirmed; the written note stated and by when; the answer at B6.", "irrelevant_conduct": "ANYTHING ABOUT HOW THE PROCEDURE WOULD BE EXPLAINED, whether it would be understood, or the recipient''s background. NO QUESTION SERVES THESE AND NO CAPTURE LINE MAY REFER TO THEM.", "stated_standard": "\"a briefing on an undocumented procedure is followed by a written note within one working day.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"a briefing on an undocumented procedure is followed by a written note within one working day\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That a demonstration is better than a walkthrough; that any part should come first; anything about teaching or explaining as a skill.", "compatibility_class": "S2-SEVEN-BEAT", "recipient_roles": [{"id": "RR1", "text": "the new team member"}, {"id": "RR2", "text": "the shift supervisor"}, {"id": "RR3", "text": "the site safety record"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the isolation sequence"}, {"id": "MI2", "text": "the emergency stop"}, {"id": "MI3", "text": "the spill response"}, {"id": "MI4", "text": "that no written form exists for this machine"}], "designated_answer_contents": [{"id": "AC1", "text": "which of the three parts will be covered and in what form"}, {"id": "AC2", "text": "that a written note follows within one working day"}], "unconfirmed_items": [{"id": "UC1", "text": "the arrival date of the manufacturer''s documentation"}], "available_channels": [{"id": "CH1", "text": "a spoken walkthrough at the machine"}, {"id": "CH2", "text": "a supervised demonstration on the floor"}], "designated_points": "Before the shift starts at six; the written note within one working day.", "question_put": "\"There''s no written procedure for that machine. What are you giving them?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": null, "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": null, "statement_test_point": "B6", "list_note": "Not selectable in available_channels: the written note within one working day.", "source_note": "Re-framed from the library scenario: The library scenario turns on a named colleague whose English is limited, and on whether the participant''s explanation reached them. BOTH ARE REMOVED. THERE IS NO LANGUAGE, COMPREHENSION OR FLUENCY ELEMENT ANYWHERE IN THIS SOURCE, and no question observes whether the recipient understood. What remains is a communication that must happen when the standard written form does not exist, which is what SC-D4-7 is.", "situation_class_label": "A communication whose standard channel, form or timing is unavailable", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D4-S2-008", "stage_code": "S2", "source_version_hash": "1df4ed6efeff8774b5ce28a09dc381fab3294a4997b8102234d45271588df6e3", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S2-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S3-001', 'source'::public.t3a_content_family, 'THE WEEKEND OUTAGE AND THE LETTER THAT FOLLOWED', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE WEEKEND OUTAGE AND THE LETTER THAT FOLLOWED", "source_digest": "f5960ce30a0ea0509a0111f4740bfecd9149a140e0e03931f4e1facb7b5691e2", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You hold the client relationship. Over the weekend the client organization experienced a system outage during their peak dispatch window; assignments failed to populate for roughly ninety minutes. Their operations director emailed your vice-president late Sunday night, copying you. Your vice-president forwarded it Monday morning with one line: \"Own this. I want to see your plan before anything goes to the client.\" Your engineering thread holds conflicting accounts — the lead engineer attributes it to a third-party rate limit, a junior engineer says warning signs were seen two weeks earlier. Neither is confirmed. No postmortem has started. The client''s deadline is Wednesday at 5:00 PM."}], "submission_instructions": "Produce the response you would send to the operations director; an internal note to your vice-president stating what is known and what is not; and a short statement of what you chose to say, what you chose not to say, and how you handled the conflicting internal accounts. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles across two deliverables"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "The written response makes the order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "The email puts a question"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "TWO unconfirmed accounts, and identifying them as unconfirmed is what this source exercises best"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "Three channels evidenced in the submission"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "The brief asks when the client next hears"}, {"question": "Q-D4-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "MI1", "Item text": "the ninety-minute duration and the window affected", "Where the participant meets it": "Pack document D1", "Quoted text": "window; assignments failed to populate for roughly ninety"}, {"Item": "MI2", "Item text": "that no root cause is confirmed", "Where the participant meets it": "Pack document D1", "Quoted text": "Neither is confirmed. No postmortem has started"}, {"Item": "MI3", "Item text": "that no postmortem has started", "Where the participant meets it": "Pack document D1", "Quoted text": "No postmortem has started"}, {"Item": "MI4", "Item text": "when the client will next hear", "Where the participant meets it": "Pack document D1", "Quoted text": "The client''s deadline is Wednesday at 5:00 PM"}, {"Item": "UC1", "Item text": "the third-party rate limit account", "Where the participant meets it": "Pack document D1", "Quoted text": "accounts — the lead engineer attributes it to a third-party rate limit"}, {"Item": "UC2", "Item text": "the earlier-warning-signs account", "Where the participant meets it": "Pack document D1", "Quoted text": "accounts — the lead engineer attributes it to a third-party rate limit, a junior engineer says warning signs were seen two weeks"}], "source_sheet": {"d4_situation_class": "SC-D4-2", "workplace_demand": "Answering an affected client about an outage whose cause is not confirmed, and reporting internally what is and is not known.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order in which they were given; whether the question put was answered; whether unconfirmed items were identified as unconfirmed; which channel was used and at which point; the further communication stated.", "irrelevant_conduct": "Who caused the outage, WHICH IS A D2 MATTER; the technical merits; the client''s tone.", "stated_standard": "\"I want to see your plan before anything goes to the client.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"I want to see your plan before anything goes to the client\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That either engineering account is true; that the participant should repeat or suppress the junior engineer''s claim; anything about diplomacy.", "compatibility_class": "S3-ASYNC-SUBMISSION", "recipient_roles": [{"id": "RR1", "text": "the client''s operations director"}, {"id": "RR2", "text": "the vice-president"}, {"id": "RR3", "text": "the engineering lead"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the ninety-minute duration and the window affected"}, {"id": "MI2", "text": "that no root cause is confirmed"}, {"id": "MI3", "text": "that no postmortem has started"}, {"id": "MI4", "text": "when the client will next hear"}], "designated_answer_contents": [{"id": "AC1", "text": "that the cause is under investigation"}, {"id": "AC2", "text": "the date of the next communication"}], "unconfirmed_items": [{"id": "UC1", "text": "the third-party rate limit account"}, {"id": "UC2", "text": "the earlier-warning-signs account"}], "available_channels": [{"id": "CH1", "text": "a written response to the operations director"}, {"id": "CH2", "text": "the internal note to the vice-president"}], "designated_points": "Before anything goes to the client; before Wednesday 5:00 PM.", "question_put": "The operations director''s email asks what happened and what is being done — exact text in the brief.", "contradicted_attribution": null, "adverse_effect_party": "The client''s operations director.", "escalation_state": "The matter has gone from the participant to the vice-president.", "conflicting_instructions": null, "ungrantable_request": null, "list_note": "Not selectable in available_channels: a call to the operations director.", "source_note": "Shared with SRC-D2-S3-001.", "situation_class_label": "Information that will adversely affect the party who receives it", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D4-S3-001", "stage_code": "S3", "source_version_hash": "f5960ce30a0ea0509a0111f4740bfecd9149a140e0e03931f4e1facb7b5691e2", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S3-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S3-002', 'source'::public.t3a_content_family, 'THE STAKEHOLDERS ON DIFFERENT PAGES', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE STAKEHOLDERS ON DIFFERENT PAGES", "source_digest": "e33cb10041d8d5acd919c25d791302711a6673b6ee15a868ede3135df571474b", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You coordinate a program with three stakeholder groups: the sponsor, the operations teams who will use the new system, and the finance function that holds the budget. A change to the rollout has been agreed: two of five sites move from March to June. What the record shows: the sponsor agreed the change; the operations teams at those two sites have not been told and have already scheduled training; finance has been told and has re-profiled the budget; the reason for the change is a supplier delay confirmed in writing; and the revised dates for the two sites are agreed with the supplier but not yet confirmed with the sites."}], "submission_instructions": "Produce the communication to the operations teams at the two affected sites; a note to the sponsor stating what you have said and to whom; and a statement of what remains unconfirmed and who must confirm it. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three stakeholder groups, one identified as the recipient"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "A written communication makes the order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "The brief puts the question of what the sites are told"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The site dates are recorded as unconfirmed"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "Three channels evidenced"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "The brief asks who must confirm and when"}, {"question": "Q-D4-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "MI1", "Item text": "the move from March to June", "Where the participant meets it": "Pack document D1", "Quoted text": "move from March to June"}, {"Item": "MI2", "Item text": "the supplier delay as the confirmed reason", "Where the participant meets it": "Pack document D1", "Quoted text": "supplier delay confirmed in writing; and the revised dates for the two sites are agreed with the supplier but not yet confirmed"}, {"Item": "MI3", "Item text": "that scheduled training will need to move", "Where the participant meets it": "Pack document D1", "Quoted text": "scheduled training; finance has"}, {"Item": "MI4", "Item text": "that finance has re-profiled", "Where the participant meets it": "Pack document D1", "Quoted text": "finance has been told and has re-profiled the budget"}, {"Item": "UC1", "Item text": "the revised dates as they apply to the two sites", "Where the participant meets it": "Pack document D1", "Quoted text": "in writing; and the revised dates for the two sites are agreed with the supplier but not yet confirmed with the sites"}], "source_sheet": {"d4_situation_class": "SC-D4-2", "workplace_demand": "Telling the groups affected by an agreed rollout change, including one that has not yet been told.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order in which they were given; whether the question put was answered; whether unconfirmed items were identified as unconfirmed; which channel was used and at which point; the further communication stated.", "irrelevant_conduct": "Who agreed the change and when, WHICH IS A D2 MATTER; the supplier''s performance.", "stated_standard": "\"the revised dates are agreed with the supplier but not yet confirmed with the sites.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"move from March to June\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the sites should have been told first; that the delay reflects on anyone; anything about stakeholder management as a skill.", "compatibility_class": "S3-ASYNC-SUBMISSION", "recipient_roles": [{"id": "RR1", "text": "the operations teams at the two sites"}, {"id": "RR2", "text": "the sponsor"}, {"id": "RR3", "text": "finance"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the move from March to June"}, {"id": "MI2", "text": "the supplier delay as the confirmed reason"}, {"id": "MI3", "text": "that scheduled training will need to move"}, {"id": "MI4", "text": "that finance has re-profiled"}], "designated_answer_contents": [{"id": "AC1", "text": "the revised dates"}, {"id": "AC2", "text": "that the dates are agreed with the supplier and not with the sites"}], "unconfirmed_items": [{"id": "UC1", "text": "the revised dates as they apply to the two sites"}], "available_channels": [{"id": "CH1", "text": "a written communication to the site teams"}, {"id": "CH2", "text": "a note to the sponsor"}], "designated_points": "Before the scheduled training dates.", "question_put": "The brief asks what the site teams are told — exact text.", "contradicted_attribution": null, "adverse_effect_party": "The operations teams at the two sites.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": null, "list_note": "Not selectable in available_channels: a site briefing.", "source_note": null, "situation_class_label": "Information that will adversely affect the party who receives it", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D4-S3-002", "stage_code": "S3", "source_version_hash": "e33cb10041d8d5acd919c25d791302711a6673b6ee15a868ede3135df571474b", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S3-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S3-003', 'source'::public.t3a_content_family, 'FIVE DAYS OUT, AND FOUR GROUPS TO TELL', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "FIVE DAYS OUT, AND FOUR GROUPS TO TELL", "source_digest": "7c5f99490435730894e188c9aeb04eea773a0ebba0ec0872770460b128b117e8", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are an implementation lead. A migration to your platform was planned for six weeks; a regulatory deadline on the client''s side pulled go-live forward by two weeks and you are five days out. The engineering lead reports that migration testing is seventy per cent complete and the remaining thirty per cent is the most complex module, needing about three further days. The account manager reports that the client expects a full cutover with no phased fallback. What the record shows: the engagement terms require completed testing before any module goes live; the go-live date is fixed by the client''s regulatory deadline; the three-day estimate is the engineering lead''s and has not been re-checked; and four groups need to hear something before Monday — the client sponsor, the client''s own operations team, your engineering team, and your account manager."}], "submission_instructions": "Produce the communication to the client sponsor; a note to the internal groups stating what each needs to know; and a statement of what is not yet confirmed and who confirms it. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "FOUR addressable roles — the largest recipient set in the estate"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"q