  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S4-003', 'source'::public.t3a_content_family, 'THE BRIEFING WITH INCOMPLETE FACTS', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE BRIEFING WITH INCOMPLETE FACTS", "source_digest": "77caac2bcfa85518cf48a3a3ede39623dd5e8383ede0d5fd764a66dfd0bd7086", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "An incident affecting a client service occurred overnight and a briefing must be given this morning. What the record shows: the service was unavailable from 02:10 to 05:40; the affected client count is 1,180 and is confirmed; the cause is not established; the standard incident briefing template requires a cause section and a remediation section, and neither can be completed; site policy requires that an incident briefing is given within four hours of service restoration whether or not the cause is known; and restoration was at 05:40.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Service was down overnight and the briefing is due within four hours of restoration. I will go round in this order — service desk, engineering, client relations, then the briefing. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What are you briefing?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "The template needs a cause and a remediation. What goes in those sections?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What written statement goes out, to whom, and by when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the client count is confirmed. Is it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the service desk lead, state the call volume since 06:00."}, {"Co-participant": "CP-2", "Position stated at the round": "As the engineering lead, state that the cause is not established."}, {"Co-participant": "CP-3", "Position stated at the round": "As the client relations lead, state that three clients have asked for a written statement."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "A template with sections makes the order explicit"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "TWO unconfirmed items, and the template forces the participant to address both"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "THE STANDARD FORM CANNOT CARRY THE COMMUNICATION — the situation this class exists for"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what goes out, to whom and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at B6"}], "material_map": [{"Item": "MI1", "Item text": "the outage window 02:10 to 05:40", "Where the participant meets it": "The pre-brief", "Quoted text": "the service was unavailable from 02:10 to 05:40"}, {"Item": "MI2", "Item text": "the confirmed client count of 1,180", "Where the participant meets it": "Beat B6", "Quoted text": "client count is confirmed"}, {"Item": "MI3", "Item text": "that the cause is not established", "Where the participant meets it": "The pre-brief", "Quoted text": "cause is not established; the standard incident briefing template requires a cause section and a remediation section, and neither can be completed"}, {"Item": "MI4", "Item text": "that the briefing is due within four hours of restoration", "Where the participant meets it": "Beat B1", "Quoted text": "briefing is due within four hours of restoration"}, {"Item": "UC1", "Item text": "the cause", "Where the participant meets it": "The pre-brief", "Quoted text": "the cause is not established"}, {"Item": "UC2", "Item text": "the remediation", "Where the participant meets it": "The pre-brief", "Quoted text": "a cause section and a remediation section, and neither can be completed"}], "source_sheet": {"d4_situation_class": "SC-D4-7", "workplace_demand": "Giving an incident briefing on time when the template cannot be completed and the cause is not known.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order in which they were given; whether the question put was answered; whether unconfirmed items were identified as unconfirmed; which channel was used and at which point; the further communication stated; what was stated when the earlier statement was put back.", "irrelevant_conduct": "The technical cause; the co-participants'' statements.", "stated_standard": "\"an incident briefing is given within four hours of service restoration whether or not the cause is known.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"an incident briefing is given within four hours of service restoration whether or not the cause is known\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the briefing should be delayed; that the empty sections reflect on anyone; anything about composure.", "compatibility_class": "S4-GROUP-ROUND", "recipient_roles": [{"id": "RR1", "text": "the briefing audience"}, {"id": "RR2", "text": "the three clients who asked for a statement"}, {"id": "RR3", "text": "the engineering lead"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the outage window 02:10 to 05:40"}, {"id": "MI2", "text": "the confirmed client count of 1,180"}, {"id": "MI3", "text": "that the cause is not established"}, {"id": "MI4", "text": "that the briefing is due within four hours of restoration"}], "designated_answer_contents": [{"id": "AC1", "text": "that the cause section cannot be completed and why"}, {"id": "AC2", "text": "what will be given instead and when the gap closes"}], "unconfirmed_items": [{"id": "UC1", "text": "the cause"}, {"id": "UC2", "text": "the remediation"}], "available_channels": [{"id": "CH1", "text": "the briefing itself"}], "designated_points": "Within four hours of 05:40.", "question_put": "\"What goes in those sections?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": "The three clients.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": "A complete template, which cannot be given.", "statement_test_point": "B6", "list_note": "Not selectable in available_channels: a written statement to the three clients; a follow-up briefing once the cause is known.", "source_note": null, "situation_class_label": "A communication whose standard channel, form or timing is unavailable", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D4-S4-003", "stage_code": "S4", "source_version_hash": "77caac2bcfa85518cf48a3a3ede39623dd5e8383ede0d5fd764a66dfd0bd7086", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S4-003' and family = 'source'::public.t3a_content_family;
