  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE BRIEFING THAT CANNOT USE THE STANDARD PACK", "source_digest": "e4ed60a86042c8741b35fe42672d8a8ae6243f060ebfa9b4683b0fc7513e40b4", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "A program briefing is scheduled for a joint group this morning. What the record shows: the standard briefing pack is embargoed until a date two weeks after the briefing, under a confidentiality undertaking given to a third party; three of its eight slides carry material that is not embargoed; the embargo is documented and its end date is fixed; the briefing cannot be postponed because the group convenes quarterly; and the program''s own status summary, which is not embargoed, is one page.", "script": [{"beat": "B1", "type": "SAY", "spoken": "The briefing is this morning and the pack is embargoed. I will go round in this order — first group, second group, governance, then the briefing. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What are you briefing this morning?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "The pack is embargoed. What does the group get?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What follows, to whom, and by when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the embargo lifts in two weeks. Is that date fixed?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "State that your group expects the full pack."}, {"Co-participant": "CP-2", "Position stated at the round": "State that the last briefing used the pack and people will notice."}, {"Co-participant": "CP-3", "Position stated at the round": "As the program governance lead, state that the embargo is documented and cannot be waived here."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "NOT SERVED", "basis": "The situation lists no unconfirmed item"}, {"question": "Q-D4-05b", "state": "NOT SERVED", "basis": "The source designates no unconfirmed_items item, so the bound question cannot be offered"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "TWO CHANNELS PERFORMABLE IN SESSION and the standard form unavailable"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what follows and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at B6"}], "material_map": [{"Item": "MI1", "Item text": "that the pack is embargoed and until when", "Where the participant meets it": "The pre-brief", "Quoted text": "pack is embargoed until a date two weeks after the briefing, under a confidentiality undertaking given to a third party; three of"}, {"Item": "MI2", "Item text": "that three of its eight slides are not embargoed", "Where the participant meets it": "The pre-brief", "Quoted text": "under a confidentiality undertaking given to a third party; three of its eight slides carry material that is not embargoed; the embargo"}, {"Item": "MI3", "Item text": "the one-page status summary", "Where the participant meets it": "The pre-brief", "Quoted text": "status summary, which is not embargoed, is one page"}, {"Item": "MI4", "Item text": "that the group convenes quarterly", "Where the participant meets it": "The pre-brief", "Quoted text": "group convenes quarterly; and"}], "source_sheet": {"d4_situation_class": "SC-D4-7", "workplace_demand": "Giving a scheduled briefing when the standard pack is embargoed.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order in which they were given; whether the question put was answered; which channel was used and at which point; the further communication stated; what was stated when the earlier statement was put back.", "irrelevant_conduct": "The co-participants'' expectations; the third party''s undertaking.", "stated_standard": "\"the embargo is documented and its end date is fixed.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"the embargo is documented and its end date is fixed\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the briefing should be postponed; that the group should be told less or more; ANYTHING ABOUT HOW THE MATERIAL WOULD BE PUT ACROSS.", "compatibility_class": "S4-GROUP-ROUND", "recipient_roles": [{"id": "RR1", "text": "the joint group"}, {"id": "RR2", "text": "the program governance lead"}, {"id": "RR3", "text": "the third party holding the undertaking"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the pack is embargoed and until when"}, {"id": "MI2", "text": "that three of its eight slides are not embargoed"}, {"id": "MI3", "text": "the one-page status summary"}, {"id": "MI4", "text": "that the group convenes quarterly"}], "designated_answer_contents": [{"id": "AC1", "text": "what will be briefed from the unembargoed material"}, {"id": "AC2", "text": "what will follow when the embargo lifts"}], "unconfirmed_items": [], "available_channels": [{"id": "CH1", "text": "the spoken briefing from the unembargoed material"}, {"id": "CH2", "text": "circulation of the one-page status summary"}], "designated_points": "This morning; the embargo end date.", "question_put": "\"What does the group get?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": "The joint group, who will not get the pack.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": "The full pack, which the undertaking forbids.", "statement_test_point": "B6", "list_note": "Not selectable in available_channels: the full pack once the embargo lifts.", "source_note": "Re-framed from the library scenario: The library scenario has the participant translating between parties who cannot understand each other. THE COMPREHENSION PREMISE IS REMOVED ENTIRELY. No question observes whether anyone understood, no capture line refers to how anything was put, and no person''s language or comprehension is part of the stimulus. What remains is a briefing that must happen when the standard pack cannot be used, which is SC-D4-7.", "situation_class_label": "A communication whose standard channel, form or timing is unavailable", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D4-S4-004", "stage_code": "S4", "source_version_hash": "e4ed60a86042c8741b35fe42672d8a8ae6243f060ebfa9b4683b0fc7513e40b4", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S4-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S4-005', 'source'::public.t3a_content_family, 'THE NEWS NOBODY WANTS TO CARRY', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE NEWS NOBODY WANTS TO CARRY", "source_digest": "4ba123d51b3453c9e3c9a468ccf1737cc3c50e52a0953e5159c5be0d53fd6758", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "A committee must decide what is communicated about a service closure. What the record shows: the service closes on the last day of next month; eleven staff are affected and all have been told individually; three hundred service users have not been told; an alternative provider has been identified and its capacity is confirmed for two hundred and forty of the three hundred; the remaining sixty have no identified alternative; and the closure decision is final and not open to representation.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We need to settle what goes to service users about the closure. I will go round in this order — communications, service delivery, the funder, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What are the users told?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What do the sixty without an alternative hear?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What goes out, to whom, and by when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said capacity is confirmed for all of them. Is it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As communications, state that a single public statement is needed this week."}, {"Co-participant": "CP-2", "Position stated at the round": "As service delivery, state that sixty users have no alternative."}, {"Co-participant": "CP-3", "Position stated at the round": "As the funder representative, state that the decision is final."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable groups, one a subset of another. WHETHER THE SIXTY ARE ADDRESSED SEPARATELY IS THE SITUATION"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "The alternative for the sixty is recorded as absent"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "Three channels, two of them performable in session"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what goes out, to whom, by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "MI1", "Item text": "the closure date", "Where the participant meets it": "The pre-brief", "Quoted text": "the service closes on the last day of next month"}, {"Item": "MI2", "Item text": "that an alternative provider is identified", "Where the participant meets it": "The pre-brief", "Quoted text": "alternative provider has been identified and its capacity is confirmed for two hundred and forty of the three hundred; the remaining sixty"}, {"Item": "MI3", "Item text": "that capacity is confirmed for two hundred and forty", "Where the participant meets it": "The pre-brief", "Quoted text": "been told; an alternative provider has been identified and its capacity is confirmed for two hundred and forty of the three hundred"}, {"Item": "MI4", "Item text": "that sixty have no identified alternative", "Where the participant meets it": "The pre-brief", "Quoted text": "identified and its capacity is confirmed for two hundred and forty of the three hundred; the remaining sixty have no identified alternative"}, {"Item": "UC1", "Item text": "any alternative for the remaining sixty", "Where the participant meets it": "The pre-brief", "Quoted text": "alternative provider has been identified and its capacity is confirmed for two hundred and forty of the three hundred; the remaining sixty"}], "source_sheet": {"d4_situation_class": "SC-D4-2", "workplace_demand": "Settling what service users are told about a closure that leaves some with no alternative.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order in which they were given; whether the question put was answered; whether unconfirmed items were identified as unconfirmed; which channel was used and at which point; the further communication stated; what was stated when the earlier statement was put back.", "irrelevant_conduct": "The closure decision; the co-participants'' positions.", "stated_standard": "\"capacity is confirmed for two hundred and forty of the three hundred.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"capacity is confirmed for two hundred and forty of the three hundred\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That a single statement is better than two; that the sixty should be told separately; anything about sensitivity.", "compatibility_class": "S4-GROUP-ROUND", "recipient_roles": [{"id": "RR1", "text": "the three hundred service users"}, {"id": "RR2", "text": "the sixty with no alternative"}, {"id": "RR3", "text": "the funder representative"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the closure date"}, {"id": "MI2", "text": "that an alternative provider is identified"}, {"id": "MI3", "text": "that capacity is confirmed for two hundred and forty"}, {"id": "MI4", "text": "that sixty have no identified alternative"}], "designated_answer_contents": [{"id": "AC1", "text": "the closure date and the alternative"}, {"id": "AC2", "text": "that sixty have no alternative yet and what happens next for them"}], "unconfirmed_items": [{"id": "UC1", "text": "any alternative for the remaining sixty"}], "available_channels": [{"id": "CH1", "text": "the committee itself"}], "designated_points": "This week; before the closure date.", "question_put": "\"What do the sixty without an alternative hear?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": "The three hundred users, and the sixty in particular.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": "An alternative for the sixty, which does not exist.", "statement_test_point": "B6", "list_note": "Not selectable in available_channels: a written statement to all users; individual contact with the sixty.", "source_note": null, "situation_class_label": "Information that will adversely affect the party who receives it", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D4-S4-005", "stage_code": "S4", "source_version_hash": "4ba123d51b3453c9e3c9a468ccf1737cc3c50e52a0953e5159c5be0d53fd6758", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S4-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S4-006', 'source'::public.t3a_content_family, 'THE DISAGREEMENT IN FRONT OF THE CLIENT', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE DISAGREEMENT IN FRONT OF THE CLIENT", "source_digest": "0f615c507c8e877aa020ba022bd2d54ea38d1aa6ca1731bd7b1afb6089e377d2", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "A client review is under way with the client''s representative present. What the record shows: the delivery approach recorded in the project plan is a phased rollout; a colleague has just proposed a single cutover in the meeting, which is not what the plan records; the client representative has asked which it is; the plan was signed by both parties six weeks ago; and no change request has been raised.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have two versions of the delivery approach in the room and the client needs an answer. I will go round in this order — delivery colleague, client representative, delivery manager, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Which approach applies?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "The plan is signed. What is the position for the client today?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What goes to the client in writing, and by when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the plan allows either. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the colleague, state that a single cutover is faster and that you have always assumed that was the plan."}, {"Co-participant": "CP-2", "Position stated at the round": "As the client representative, state that you need to know which approach applies."}, {"Co-participant": "CP-3", "Position stated at the round": "As the delivery manager, state that no change request has been raised."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles, one of them the client"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "NOT SERVED", "basis": "The situation lists no unconfirmed item"}, {"question": "Q-D4-05b", "state": "NOT SERVED", "basis": "The source designates no unconfirmed_items item, so the bound question cannot be offered"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "Two channels performable in session"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what goes in writing and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "statement_test_point at B6"}], "material_map": [{"Item": "MI1", "Item text": "that the signed plan records a phased rollout", "Where the participant meets it": "The pre-brief", "Quoted text": "record shows: the delivery approach recorded in the project plan is a phased rollout; a colleague has just proposed a single cutover"}, {"Item": "MI2", "Item text": "that no change request has been raised", "Where the participant meets it": "The pre-brief", "Quoted text": "change request has been raised"}, {"Item": "MI3", "Item text": "that the plan was signed by both parties six weeks ago", "Where the participant meets it": "The pre-brief", "Quoted text": "what the plan records; the client representative has asked which it is; the plan was signed by both parties six weeks ago"}, {"Item": "MI4", "Item text": "what would be needed to change it", "Where the participant meets it": "The pre-brief", "Quoted text": "no change request has been raised"}], "source_sheet": {"d4_situation_class": "SC-D4-1", "workplace_demand": "Answering a client who has heard two versions of the delivery approach in one meeting.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order in which they were given; whether the question put was answered; which channel was used and at which point; the further communication stated; what was stated when the earlier statement was put back.", "irrelevant_conduct": "Which approach is better, WHICH IS A D3 MATTER; the colleague''s assumption.", "stated_standard": "\"the delivery approach recorded in the project plan is a phased rollout.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"the delivery approach recorded in the project plan is a phased rollout\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the colleague should have been corrected in front of the client or afterwards; anything about tact. NO RENDERED STATEMENT NAMES THE COLLEAGUE.", "compatibility_class": "S4-GROUP-ROUND", "recipient_roles": [{"id": "RR1", "text": "the client representative"}, {"id": "RR2", "text": "the colleague"}, {"id": "RR3", "text": "the delivery manager"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the signed plan records a phased rollout"}, {"id": "MI2", "text": "that no change request has been raised"}, {"id": "MI3", "text": "that the plan was signed by both parties six weeks ago"}, {"id": "MI4", "text": "what would be needed to change it"}], "designated_answer_contents": [{"id": "AC1", "text": "the phased rollout as the plan records it"}, {"id": "AC2", "text": "the change route if a different approach is wanted"}], "unconfirmed_items": [], "available_channels": [{"id": "CH1", "text": "the review meeting"}], "designated_points": "In this meeting; in writing afterwards.", "question_put": "\"What is the position for the client today?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": null, "escalation_state": null, "conflicting_instructions": "The colleague''s proposal against the signed plan; the plan is independently established in the pre-brief.", "ungrantable_request": null, "statement_test_point": "B6", "list_note": "Not selectable in available_channels: a written confirmation to the client; a change request.", "source_note": "contradicted_attribution: The colleague misstates the plan, not something attributed to P-OBS.", "situation_class_label": "A question put in front of others before an answer can be prepared", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D4-S4-006", "stage_code": "S4", "source_version_hash": "0f615c507c8e877aa020ba022bd2d54ea38d1aa6ca1731bd7b1afb6089e377d2", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S4-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S4-007', 'source'::public.t3a_content_family, 'THE POSITION THAT MUST GO UPWARD', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE POSITION THAT MUST GO UPWARD", "source_digest": "714081154f8ea4825b54c29596952a5818d33b3701528f1557536b4d5890dcf7", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "A decision has been taken above you and a group has been convened to work out how to implement it. What the record shows: the decision is to consolidate two support desks into one from the first of next quarter; the stated saving is nine full-time equivalents; the volume data shows the combined desks handled 41,000 contacts last year against a benchmark capacity of 33,000 for the proposed structure; the volume data is from the firm''s own reporting system and is not disputed; and the decision-maker has asked the group for an implementation plan, not for a view on the decision.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have been asked for an implementation plan for the consolidation. I will go round in this order — planning, data, the decision-maker''s office, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What is your input to the plan?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "The ask is a plan, not a view. What do you want recorded?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What goes upward in writing, to whom, and by when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the volume figures are disputed. Are they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "State that the plan is what has been asked for."}, {"Co-participant": "CP-2", "Position stated at the round": "State that the volume figures are what they are."}, {"Co-participant": "CP-3", "Position stated at the round": "As the decision-maker''s representative, state that the decision is not reopening."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "NOT SERVED", "basis": "The situation lists no unconfirmed item"}, {"question": "Q-D4-05b", "state": "NOT SERVED", "basis": "The source designates no unconfirmed_items item, so the bound question cannot be offered"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "Two channels performable in session"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what goes upward, to whom, by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "MI1", "Item text": "the 41,000 contacts against 33,000 benchmark capacity", "Where the participant meets it": "The pre-brief", "Quoted text": "contacts last year against a benchmark capacity"}, {"Item": "MI2", "Item text": "that the data is from the firm''s own system and undisputed", "Where the participant meets it": "The pre-brief", "Quoted text": "last year against a benchmark capacity of 33,000 for the proposed structure; the volume data is from the firm''s own reporting system"}, {"Item": "MI3", "Item text": "the first of next quarter effective date", "Where the participant meets it": "The pre-brief", "Quoted text": "first of next quarter"}, {"Item": "MI4", "Item text": "that the ask is for a plan, not a view", "Where the participant meets it": "Beat B4", "Quoted text": "ask is a plan, not a view"}], "source_sheet": {"d4_situation_class": "SC-D4-6", "workplace_demand": "Communicating an implementation position upward when the volume data does not support the decision.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order in which they were given; whether the question put was answered; which channel was used and at which point; the further communication stated; what was stated when the earlier statement was put back.", "irrelevant_conduct": "The merits of the consolidation; the co-participants'' positions.", "stated_standard": "\"the decision-maker has asked the group for an implementation plan, not for a view on the decision.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"the decision-maker has asked the group for an implementation plan, not for a view on the decision\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That raising the figures was required or unwise; that the decision is wrong; anything about courage.", "compatibility_class": "S4-GROUP-ROUND", "recipient_roles": [{"id": "RR1", "text": "the decision-maker, through their representative"}, {"id": "RR2", "text": "the group"}, {"id": "RR3", "text": "the data owner"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the 41,000 contacts against 33,000 benchmark capacity"}, {"id": "MI2", "text": "that the data is from the firm''s own system and undisputed"}, {"id": "MI3", "text": "the first of next quarter effective date"}, {"id": "MI4", "text": "that the ask is for a plan, not a view"}], "designated_answer_contents": [{"id": "AC1", "text": "the volume figures as recorded"}, {"id": "AC2", "text": "what the plan can and cannot deliver at that capacity"}], "unconfirmed_items": [], "available_channels": [{"id": "CH1", "text": "the group meeting"}], "designated_points": "In this meeting; with the plan.", "question_put": "\"What do you want recorded?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": "The decision-maker, whose stated ask the figures cut against.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": "A plan that meets the stated saving at the recorded volumes.", "statement_test_point": "B6", "list_note": "Not selectable in available_channels: a written note upward; a request to reopen the decision.", "source_note": null, "situation_class_label": "A request that cannot be granted as asked", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D4-S4-007", "stage_code": "S4", "source_version_hash": "714081154f8ea4825b54c29596952a5818d33b3701528f1557536b4d5890dcf7", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S4-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S4-009', 'source'::public.t3a_content_family, 'THE UPDATE WITH NOTHING CONFIRMED', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE UPDATE WITH NOTHING CONFIRMED", "source_digest": "387940ee24b5bcdc5dc3812559b7c1f5e75caa79b2df6026ec1acc35f8a24a06", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "A weekly program update is due to a steering group this morning and the reporting system has been unavailable since Friday. What the record shows: the standard update draws six metrics from that system; none can be produced this week; the previous week''s figures are available from the last issued report; the steering group''s terms of reference require an update at every weekly meeting; and the system supplier has given no restoration time.", "script": [{"beat": "B1", "type": "SAY", "spoken": "The reporting system has been down since Friday and the update is due this morning. I will go round in this order — program office, workstream, the chair''s office, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What is the update this week?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "None of the six metrics is available. What does the group get?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What follows, to whom, and by when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said last week''s figures are current. Are they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the program office, state that the standard update cannot be produced."}, {"Co-participant": "CP-2", "Position stated at the round": "As a workstream lead, state that your workstream position has not changed since last week."}, {"Co-participant": "CP-3", "Position stated at the round": "As the steering group chair''s representative, state that the terms of reference require an update."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "TWO unconfirmed items, and identifying last week''s figures as last week''s is the element this source turns on"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "The standard form is unavailable — the situation this class exists for"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what follows and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "MI1", "Item text": "that the six metrics cannot be produced this week", "Where the participant meets it": "The pre-brief", "Quoted text": "six metrics from that system; none can be produced this week; the previous week''s"}, {"Item": "MI2", "Item text": "that the previous week''s figures are available and are last week''s", "Where the participant meets it": "The pre-brief", "Quoted text": "week; the previous week''s figures are available from the last"}, {"Item": "MI3", "Item text": "that no restoration time has been given", "Where the participant meets it": "The pre-brief", "Quoted text": "given no restoration time"}, {"Item": "MI4", "Item text": "that the terms of reference require an update", "Where the participant meets it": "The pre-brief", "Quoted text": "this week; the previous week''s figures are available from the last issued report; the steering group''s terms of reference require an update"}, {"Item": "UC1", "Item text": "every current-week metric", "Where the participant meets it": "The pre-brief", "Quoted text": "metrics from that system; none can be produced this week; the previous week''s figures are available from the last issued report; the"}, {"Item": "UC2", "Item text": "the restoration time", "Where the participant meets it": "The pre-brief", "Quoted text": "given no restoration time"}], "source_sheet": {"d4_situation_class": "SC-D4-7", "workplace_demand": "Giving a weekly update when none of the standard figures can be produced.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order in which they were given; whether the question put was answered; whether unconfirmed items were identified as unconfirmed; which channel was used and at which point; the further communication stated; what was stated when the earlier statement was put back.", "irrelevant_conduct": "The system failure; the co-participants'' statements.", "stated_standard": "\"the steering group''s terms of reference require an update at every weekly meeting.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"the steering group''s terms of reference require an update at every weekly meeting\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the meeting should be canceled; that last week''s figures should or should not be used; anything about resourcefulness.", "compatibility_class": "S4-GROUP-ROUND", "recipient_roles": [{"id": "RR1", "text": "the steering group"}, {"id": "RR2", "text": "the program office"}, {"id": "RR3", "text": "the system supplier"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "that the six metrics cannot be produced this week"}, {"id": "MI2", "text": "that the previous week''s figures are available and are last week''s"}, {"id": "MI3", "text": "that no restoration time has been given"}, {"id": "MI4", "text": "that the terms of reference require an update"}], "designated_answer_contents": [{"id": "AC1", "text": "what can be given from the last issued report, identified as last week''s"}, {"id": "AC2", "text": "when the current figures follow"}], "unconfirmed_items": [{"id": "UC1", "text": "every current-week metric"}, {"id": "UC2", "text": "the restoration time"}], "available_channels": [{"id": "CH1", "text": "the steering group meeting"}], "designated_points": "This morning; on restoration.", "question_put": "\"What does the group get?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": "The steering group.", "escalation_state": null, "conflicting_instructions": null, "ungrantable_request": "The standard update, which cannot be produced.", "statement_test_point": "B6", "list_note": "Not selectable in available_channels: a written interim note; the standard update once the system returns.", "source_note": null, "situation_class_label": "A communication whose standard channel, form or timing is unavailable", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D4-S4-009", "stage_code": "S4", "source_version_hash": "387940ee24b5bcdc5dc3812559b7c1f5e75caa79b2df6026ec1acc35f8a24a06", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S4-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D4-S4-010', 'source'::public.t3a_content_family, 'FOUR PARTIES, FOUR DIRECTIONS ON ONE DELIVERABLE', 'D4', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.2', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "FOUR PARTIES, FOUR DIRECTIONS ON ONE DELIVERABLE", "source_digest": "54d278f79b65bdeda0712ce398387bec444acda1988cb6c946861bdf7085f5b3", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "You hold a deliverable on which four parties have each sent a written direction. What the record shows: the sponsor''s direction is to keep the scope as contracted; the technical authority''s is to add a validation step that extends the timeline by two weeks; the user group''s is to simplify the output format; the finance function''s is that no timeline extension is funded; the contracted delivery date is in five weeks; and all four directions are in writing and none has been withdrawn.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Four directions have come in on one deliverable and they do not agree. I will go round in this order — technical authority, user group, finance, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where does the deliverable stand against the four directions?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "They cannot all be followed. What is the single position you are taking back?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What goes to each party in writing, and by when?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the sponsor has withdrawn their direction. Have they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the technical authority, state that the validation step is required."}, {"Co-participant": "CP-2", "Position stated at the round": "As the user group representative, state that the current output format is unusable."}, {"Co-participant": "CP-3", "Position stated at the round": "As finance, state that no extension is funded."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "FOUR addressable roles, and whether one message or four is sent is the situation"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "Whether any party would vary is recorded as unknown"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "The situation attributes no statement to the participant that the record contradicts"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "THREE CHANNELS PERFORMABLE IN SESSION — the widest channel choice in the estate"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what goes to each party and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "MI1", "Item text": "the four directions as written", "Where the participant meets it": "The pre-brief", "Quoted text": "four parties have each sent a written direction"}, {"Item": "MI2", "Item text": "that they cannot all be followed", "Where the participant meets it": "Beat B4", "Quoted text": "cannot all be followed"}, {"Item": "MI3", "Item text": "the contracted date five weeks out", "Where the participant meets it": "The pre-brief", "Quoted text": "simplify the output format; the finance function''s is that no timeline extension is funded; the contracted delivery date is in five weeks"}, {"Item": "MI4", "Item text": "that none has been withdrawn", "Where the participant meets it": "The pre-brief", "Quoted text": "none has been withdrawn"}, {"Item": "UC1", "Item text": "whether any party would withdraw or vary their direction", "Where the participant meets it": "The pre-brief", "Quoted text": "none has been withdrawn"}], "source_sheet": {"d4_situation_class": "SC-D4-4", "workplace_demand": "Communicating one position back on a deliverable where four written directions conflict.", "relevant_conduct": "Who was addressed; which designated items the communication contained; the order in which they were given; whether the question put was answered; whether unconfirmed items were identified as unconfirmed; which channel was used and at which point; the further communication stated; what was stated when the earlier statement was put back.", "irrelevant_conduct": "The merits of the directions; the co-participants'' insistence.", "stated_standard": "\"all four directions are in writing and none has been withdrawn.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"all four directions are in writing and none has been withdrawn\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That any direction should prevail; that a single message is better than four; anything about negotiation.", "compatibility_class": "S4-GROUP-ROUND", "recipient_roles": [{"id": "RR1", "text": "the sponsor"}, {"id": "RR2", "text": "the technical authority"}, {"id": "RR3", "text": "the user group"}, {"id": "RR4", "text": "finance"}], "intended_recipient": "RR1", "material_items": [{"id": "MI1", "text": "the four directions as written"}, {"id": "MI2", "text": "that they cannot all be followed"}, {"id": "MI3", "text": "the contracted date five weeks out"}, {"id": "MI4", "text": "that none has been withdrawn"}], "designated_answer_contents": [{"id": "AC1", "text": "the single position and which direction it follows"}, {"id": "AC2", "text": "which directions are not being followed and what is needed to resolve them"}], "unconfirmed_items": [{"id": "UC1", "text": "whether any party would withdraw or vary their direction"}], "available_channels": [{"id": "CH1", "text": "the meeting"}], "designated_points": "In this meeting; before the contracted date.", "question_put": "\"What is the single position you are taking back?\" Exact text at B4.", "contradicted_attribution": null, "adverse_effect_party": "Whichever parties'' directions are not followed.", "escalation_state": null, "conflicting_instructions": "FOUR WRITTEN DIRECTIONS, all established in the pre-brief and none created by a co-participant.", "ungrantable_request": "All four directions together.", "statement_test_point": "B6", "list_note": "Not selectable in available_channels: a single written position to all four; separate written notes to each.", "source_note": "Re-framed from the library scenario: The library scenario has the participant receiving conflicting feedback about themselves. THE FEEDBACK-ABOUT-THE-PARTICIPANT PREMISE IS REMOVED ENTIRELY. NOTHING IN THIS SOURCE IS ABOUT THE PARTICIPANT''S OWN PERFORMANCE. What remains is four written directions on one deliverable that cannot all be followed, which is SC-D4-4.", "situation_class_label": "Conflicting directions from two or more sources of instruction", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D4-S4-010", "stage_code": "S4", "source_version_hash": "54d278f79b65bdeda0712ce398387bec444acda1988cb6c946861bdf7085f5b3", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D4-S4-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_d1_content_load_event(env_state, content_object_id, content_version_id, governed_status, notes) select 'design_only', o.content_object_id, v.content_version_id, 'DISABLED_PENDING_DECISION', 'T3A-D4-EXEC-001 v2.2 loaded not servable' from public.t3a_content_object o join public.t3a_d1_content_version v on v.content_object_id = o.content_object_id where o.dimension_id = 'D4' and o.identifier like 'T3A-D4-EXEC-001%' or (o.dimension_id = 'D4' and o.identifier like 'SRC-D4-%');
